    }

private static <T extends Entity & ParchmentBoltRenderData> Vec3d resolveSmoothedOffset(T entity, float tickDelta) {
        float ageTicks = entity.age + tickDelta;
        Vec3d target = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));

        RenderState state = RENDER_STATES.computeIfAbsent(entity.getId(),
                ignored -> new RenderState(target, ageTicks));

        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.position = target;
        } else if (deltaTicks > 0.0F) {
            state.position = state.position.lerp(target,
                    Math.min(1.0F, POSITION_SMOOTHING_RATE * deltaTicks));
        }
        state.lastAgeTicks = ageTicks;

        if (entity.age % 80 == 0) {
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F);
        }
        return state.position.subtract(target);
    }

@Override
    public void render(DancingBladeVisualEntity entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        ItemStack stack = entity.getWeaponStack();
        if (stack == null || stack.isEmpty()) {
            return;
        }

        int maxSwords = Math.max(1, net.sweenus.simplyswords.config.Config.gemPowers.dancingBlades.maxSwords);
        Vec3d center = getRenderCenter(entity, tickDelta);
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ())
        );
        double baseAngle = getSmoothRenderPhase(entity, tickDelta);
        double angle = baseAngle + ((Math.PI * 2.0) / maxSwords) * entity.getOrbitSlot();
        double bob = Math.sin(baseAngle * (BOB_SPEED / BASE_ANGULAR_SPEED) + entity.getOrbitSlot() * 1.7) * BOB_AMPLITUDE;
        Vec3d bladePos = center.add(Math.cos(angle) * Math.max(0.5F, entity.getOrbitRadius()), BLADE_HEIGHT + bob, Math.sin(angle) * Math.max(0.5F, entity.getOrbitRadius()));
        Vec3d offset = bladePos.subtract(entityPos);

        float renderAge = entity.age + tickDelta;
        float attackProgress = getAttackProgress(entity, tickDelta);
        AttackPose attackPose = getAttackPose(attackProgress);
        float spin = (float) Math.toDegrees(-angle) + 90.0F;
        float idleTilt = 35.0F + MathHelper.sin(renderAge * 0.12F + entity.getOrbitSlot()) * 7.0F;

        matrices.push();
        matrices.translate(offset.x, offset.y, offset.z);
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(spin));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(idleTilt + attackPose.impactRoll));
        BakedModel model = this.itemRenderer.getModels().getModel(stack);
        this.itemRenderer.renderItem(
                stack,
                ModelTransformationMode.GROUND,
                false,
                matrices,
                vertexConsumers,
                light,
                OverlayTexture.DEFAULT_UV,
                model
        );
        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private static void drawSweepingCrescent(VertexConsumer vertices, Matrix4f matrix,
                                              float progress, float radiusX, float radiusY,
                                              float thickness, int red, int green, int blue,
                                              int alpha, int light) {
        float head = MathHelper.clamp(progress * 1.32F, 0.0F, 1.0F);
        float tail = Math.max(0.0F, head - 0.62F);
        float forwardEdge = Math.min(1.0F, head + 0.10F);
        float visibleLength = Math.max(0.05F, forwardEdge - tail);

        for (int segment = 0; segment < ARC_SEGMENTS; segment++) {
            float start = segment / (float) ARC_SEGMENTS;
            float end = (segment + 1) / (float) ARC_SEGMENTS;
            if (end < tail || start > forwardEdge) {
                continue;
            }

            float localProgress = MathHelper.clamp(
                    ((start + end) * 0.5F - tail) / visibleLength,
                    0.0F,
                    1.0F
            );
            float trailFade = MathHelper.clamp(localProgress * 2.2F, 0.08F, 1.0F);
            float headFade = MathHelper.clamp((1.0F - localProgress) * 6.0F, 0.25F, 1.0F);
            int segmentAlpha = Math.max(1, Math.round(alpha * trailFade * headFade));
            drawCrescentSegment(vertices, matrix, start, end, radiusX, radiusY, thickness,
                    red, green, blue, segmentAlpha, light);
        }
    }

private RenderPose resolveRenderPose(WraithmawCutlassEntity entity, float tickDelta) {
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        int cutlassState = entity.getState();
        Vec3d targetPosition = entityPos;
        Vec3d targetDirection = normalizedDirection(entity.getVelocity());
        if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
            Entity ownerEntity = entity.getWorld().getEntityById(entity.getOwnerId());
            if (!(ownerEntity instanceof LivingEntity owner)
                    || !owner.getMainHandStack().isOf(ItemsRegistry.WRAITHMAW.get())
                    && !owner.getOffHandStack().isOf(ItemsRegistry.WRAITHMAW.get())) {
                RENDER_STATES.remove(entity.getId());
                return null;
            }
            targetPosition = orbitPosition(entity, owner, tickDelta);
            double ownerYaw = Math.toRadians(MathHelper.lerpAngleDegrees(
                    tickDelta, owner.prevYaw, owner.getYaw()));
            targetDirection = new Vec3d(-Math.sin(ownerYaw), 0.0, Math.cos(ownerYaw));
        }

        float ageTicks = entity.age + tickDelta;
        long worldTick = entity.getWorld().getTime();
        RenderState renderState = RENDER_STATES.get(entity.getId());
        float deltaTicks = renderState == null ? 0.0F : ageTicks - renderState.lastAgeTicks;
        boolean reset = renderState == null
                || renderState.world != entity.getWorld()
                || !entity.getUuid().equals(renderState.entityUuid)
                || deltaTicks < 0.0F || deltaTicks > 5.0F;
        if (!reset && renderState.state == WraithmawCutlassEntity.STATE_ORBITING
                && cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED) {
            targetPosition = entity.getPos();
        }
        if (reset) {
            renderState = new RenderState(entity.getWorld(), entity.getUuid(), targetPosition,
                    targetDirection, ageTicks, worldTick, cutlassState);
            RENDER_STATES.put(entity.getId(), renderState);
        } else {
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.position = targetPosition;
            } else if (deltaTicks > 0.0F) {
                renderState.position = renderState.position.lerp(targetPosition,
                        response(POSITION_RESPONSE, deltaTicks));
            }
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.direction = targetDirection;
            } else if ((cutlassState == WraithmawCutlassEntity.STATE_FALLING
                    || cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED)
                    && targetDirection != null) {
                if (renderState.direction == null) {
                    renderState.direction = targetDirection;
                } else if (deltaTicks > 0.0F) {
                    renderState.direction = interpolateDirection(
                            renderState.direction, targetDirection,
                            response(DIRECTION_RESPONSE, deltaTicks));
                }
            }
            renderState.lastAgeTicks = ageTicks;
            renderState.lastWorldTick = worldTick;
            renderState.state = cutlassState;
        }
        if (entity.age % 80 == 0) {
            long cutoff = worldTick - 100L;
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId()
                            && (entry.getValue().world != entity.getWorld()
                            || entry.getValue().lastWorldTick < cutoff));
        }
        return new RenderPose(renderState.position.subtract(entityPos), renderState.direction);
    }

private static OrbitRenderPose resolveOrbitPose(ThrownSpearEntity entity, ItemStack stack,
                                                     float tickDelta) {
        if (!stack.isOf(ItemsRegistry.WICKPIERCER.get()) || !entity.hasOrbitPresentation()) {
            return null;
        }
        Entity targetEntity = entity.getWorld().getEntityById(entity.getOrbitTargetId());
        if (!(targetEntity instanceof LivingEntity target) || !target.isAlive() || target.isRemoved()) {
            return null;
        }
        int elapsedTicks = (int) entity.getWorld().getTime() - entity.getOrbitStartTick();
        double elapsed = elapsedTicks + tickDelta;
        int duration = entity.getOrbitDurationTicks();
        if (elapsed < 0.0 || elapsed > duration + 1.0) {
            return null;
        }
        double pathElapsed = Math.min(elapsed, duration);
        Vec3d targetCenter = new Vec3d(
                MathHelper.lerp(tickDelta, target.prevX, target.getX()),
                MathHelper.lerp(tickDelta, target.prevY, target.getY()) + target.getHeight() * 0.55,
                MathHelper.lerp(tickDelta, target.prevZ, target.getZ()));
        Vec3d entityPosition = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        Vec3d currentOffset = WickpiercerThrowMath.orbitOffset(
                pathElapsed, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        Vec3d desiredPosition = targetCenter.add(currentOffset);

        double sampleDistance = 0.08;
        double before = Math.max(0.0, pathElapsed - sampleDistance);
        double after = Math.min(duration, pathElapsed + sampleDistance);
        Vec3d beforeOffset = WickpiercerThrowMath.orbitOffset(
                before, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        Vec3d afterOffset = WickpiercerThrowMath.orbitOffset(
                after, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        double cycleAge = pathElapsed % entity.getOrbitIntervalTicks();
        double edgeWindow = sampleDistance;
        Vec3d direction;
        if (pathElapsed >= duration || cycleAge > entity.getOrbitIntervalTicks() - edgeWindow
                || pathElapsed > 0.0 && cycleAge < 1.0E-6) {
            direction = currentOffset.subtract(beforeOffset);
        } else if (cycleAge < edgeWindow) {
            direction = afterOffset.subtract(currentOffset);
        } else {
            direction = afterOffset.subtract(beforeOffset);
        }
        if (direction.lengthSquared() < 1.0E-6) {
            direction = entity.getVelocity();
        }
        if (direction.lengthSquared() < 1.0E-6) {
            direction = new Vec3d(0.0, 0.0, 1.0);
        }
        return new OrbitRenderPose(desiredPosition.subtract(entityPosition), direction.normalize());
    }

private void renderFootprint(World world, UUID id,
                                 double centerX, double centerY, double centerZ,
                                 SplatterShape shape, long shapeKey, float scanExtent,
                                 float fluidRadius, float verticalRange,
                                 Palette palette, float opacity,
                                 MatrixStack.Entry matrices,
                                 VertexConsumerProvider vertexConsumers) {
        opacity = MathHelper.clamp(opacity, 0.0F, 1.0F);
        if (opacity <= 0.01F || shape.parts.isEmpty()) {
            clear(id);
            return;
        }
        TerrainCache cache = getCache(
                world, id, centerX, centerY, centerZ, scanExtent, verticalRange, palette);
        if (cache.faces.isEmpty() && cache.fluidSurfaces.isEmpty()) {
            return;
        }

        SpriteSet sprites = palette.useBlockModelTextures
                ? SpriteSet.EMPTY
                : SpriteSet.load(palette);
        double minY = centerY - verticalRange;
        double maxY = centerY + verticalRange;
        PreparedGeometry preparedGeometry = prepareGeometry(
                cache, centerX, centerY, centerZ, shape, shapeKey, minY, maxY);
        List<PreparedFace> preparedFaces = preparedGeometry.faces;

        boolean translucent = opacity < 0.999F
                || shape.parts.stream().anyMatch(part -> part.opacity < 0.999F);
        VertexConsumer texturedVertices = vertexConsumers.getBuffer(
                translucent
                        ? RenderLayer.getEntityTranslucent(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE)
                        : RenderLayer.getCutout());
        for (PreparedFace prepared : preparedFaces) {
            float faceOpacity = opacity * prepared.part().opacity;
            if (palette == BLOOD_STAIN && faceOpacity >= 0.999F
                    && prepared.fullyCovered()
                    && !BLOOD_FACES_THIS_FRAME.add(prepared.face().key())) {
                continue;
            }
            if (prepared instanceof PreparedHorizontalFace horizontal) {
                drawHorizontalTextureFace(
                        centerX, centerY, centerZ, matrices, texturedVertices,
                        sprites, palette, faceOpacity, horizontal);
            } else if (prepared instanceof PreparedVerticalFace vertical) {
                drawVerticalTextureFace(
                        centerX, centerY, centerZ, matrices, texturedVertices,
                        sprites, palette, faceOpacity, vertical);
            }
        }
        if (sprites.fluidStill != null && sprites.fluidFlow != null) {
            for (SplatterPart part : shape.parts) {
                for (FluidSurface surface : cache.fluidSurfaces) {
                    drawFluidSurface(
                            centerX, centerY, centerZ,
                            matrices, texturedVertices, sprites,
                            surface, fluidRadius, part.points, minY, maxY
                    );
                }
            }
        }

        if (palette.washAlpha > 0) {
            VertexConsumer washVertices = vertexConsumers.getBuffer(
                    RenderLayer.getEntityTranslucent(WHITE_TEXTURE));
            for (PreparedFace prepared : preparedFaces) {
                float faceOpacity = opacity * prepared.part().opacity;
                if (prepared instanceof PreparedHorizontalFace horizontal) {
                    drawHorizontalWashFace(centerY, matrices, washVertices, palette, faceOpacity, horizontal);
                } else if (prepared instanceof PreparedVerticalFace vertical) {
                    drawVerticalWashFace(
                            centerX, centerY, centerZ, matrices, washVertices,
                            palette, faceOpacity, vertical);
                }
            }
        }
    }

private static FaceTextureMapping from(
                BakedQuad quad, Direction direction, Box bounds) {
            int[] data = quad.getVertexData();
            if (data.length < 24 || data.length % 4 != 0) {
                return null;
            }
            int stride = data.length / 4;
            if (stride < 6) {
                return null;
            }

            FaceBounds required = FaceBounds.of(direction, bounds);
            ModelVertex[] vertices = new ModelVertex[4];
            double actualMinFirst = Double.POSITIVE_INFINITY;
            double actualMaxFirst = Double.NEGATIVE_INFINITY;
            double actualMinSecond = Double.POSITIVE_INFINITY;
            double actualMaxSecond = Double.NEGATIVE_INFINITY;
            Sprite sprite = quad.getSprite();
            for (int i = 0; i < vertices.length; i++) {
                int offset = i * stride;
                double x = Float.intBitsToFloat(data[offset]);
                double y = Float.intBitsToFloat(data[offset + 1]);
                double z = Float.intBitsToFloat(data[offset + 2]);
                FaceCoordinates coordinates = FaceCoordinates.of(direction, x, y, z);
                double u = sprite.getFrameFromU(Float.intBitsToFloat(data[offset + 4]));
                double v = sprite.getFrameFromV(Float.intBitsToFloat(data[offset + 5]));
                vertices[i] = new ModelVertex(coordinates.first, coordinates.second, u, v);
                actualMinFirst = Math.min(actualMinFirst, coordinates.first);
                actualMaxFirst = Math.max(actualMaxFirst, coordinates.first);
                actualMinSecond = Math.min(actualMinSecond, coordinates.second);
                actualMaxSecond = Math.max(actualMaxSecond, coordinates.second);
            }
            if (actualMinFirst > required.minFirst + COVERAGE_EPSILON
                    || actualMaxFirst < required.maxFirst - COVERAGE_EPSILON
                    || actualMinSecond > required.minSecond + COVERAGE_EPSILON
                    || actualMaxSecond < required.maxSecond - COVERAGE_EPSILON) {
                return null;
            }

            ModelVertex origin = vertices[0];
            for (int first = 1; first < vertices.length; first++) {
                double firstDeltaA = vertices[first].first - origin.first;
                double firstDeltaB = vertices[first].second - origin.second;
                for (int second = first + 1; second < vertices.length; second++) {
                    double secondDeltaA = vertices[second].first - origin.first;
                    double secondDeltaB = vertices[second].second - origin.second;
                    double determinant = firstDeltaA * secondDeltaB
                            - secondDeltaA * firstDeltaB;
                    if (Math.abs(determinant) <= 1.0E-9) {
                        continue;
                    }
                    double uFirst = ((vertices[first].u - origin.u) * secondDeltaB
                            - (vertices[second].u - origin.u) * firstDeltaB) / determinant;
                    double uSecond = (firstDeltaA * (vertices[second].u - origin.u)
                            - secondDeltaA * (vertices[first].u - origin.u)) / determinant;
                    double vFirst = ((vertices[first].v - origin.v) * secondDeltaB
                            - (vertices[second].v - origin.v) * firstDeltaB) / determinant;
                    double vSecond = (firstDeltaA * (vertices[second].v - origin.v)
                            - secondDeltaA * (vertices[first].v - origin.v)) / determinant;
                    return new FaceTextureMapping(
                            origin.u - uFirst * origin.first - uSecond * origin.second,
                            uFirst, uSecond,
                            origin.v - vFirst * origin.first - vSecond * origin.second,
                            vFirst, vSecond,
                            required.minFirst, required.maxFirst,
                            required.minSecond, required.maxSecond);
                }
            }
            return null;
        }

@Override
	public void onUseTick(Level world, LivingEntity living, ItemStack stack, int count) {
		int spawned = getWeaponsSpawned(stack);

		if (count != getUseDuration(stack) && spawned < 20 && !world.isClientSide && (!(living instanceof Player player) || ManaItemHandler.instance().requestManaExact(stack, player, 150, true))) {
			Vec3 look = living.getLookAngle().multiply(1, 0, 1);

			double playerRot = Math.toRadians(living.getYRot() + 90);
			if (look.x == 0 && look.z == 0) {
				look = new Vec3(Math.cos(playerRot), 0, Math.sin(playerRot));
			}

			look = look.normalize().scale(-2);

			int div = spawned / 5;
			int mod = spawned % 5;

			Vec3 pl = look.add(VecHelper.fromEntityCenter(living)).add(0, 1.6, div * 0.1);

			var rand = world.random;
			Vec3 axis = look.normalize().cross(new Vec3(-1, 0, -1)).normalize();

			double rot = mod * Math.PI / 4 - Math.PI / 2;

			Vec3 axis1 = VecHelper.rotate(axis.scale(div * 3.5 + 5), rot, look);
			if (axis1.y < 0) {
				axis1 = axis1.multiply(1, -1, 1);
			}

			Vec3 end = pl.add(axis1);

			BabylonWeaponEntity weapon = new BabylonWeaponEntity(living, world);
			weapon.setPos(end.x, end.y, end.z);
			weapon.setYRot(living.getYRot());
			weapon.setVariety(rand.nextInt(WEAPON_TYPES));
			weapon.setDelay(spawned);
			weapon.setRotation(Mth.wrapDegrees(-living.getYRot() + 180));

			world.addFreshEntity(weapon);
			weapon.playSound(BotaniaSounds.babylonSpawn, 1F, 1F + world.random.nextFloat() * 3F);
			setWeaponsSpawned(stack, spawned + 1);
		}
	}

@Override
		public void doRender(HumanoidModel<?> bipedModel, ItemStack stack, LivingEntity living, PoseStack ms, MultiBufferSource buffers, int light, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
			CloakOfVirtueItem item = ((CloakOfVirtueItem) stack.getItem());
			AccessoryRenderHelper.rotateIfSneaking(ms, living);
			boolean armor = !living.getItemBySlot(EquipmentSlot.CHEST).isEmpty();
			ms.translate(0F, armor ? -0.07F : -0.01F, 0F);

			if (model == null) {
				model = new CloakModel(Minecraft.getInstance().getEntityModels().bakeLayer(BotaniaModelLayers.CLOAK));
			}

			VertexConsumer buffer = buffers.getBuffer(model.renderType(item.getCloakTexture()));
			model.renderToBuffer(ms, buffer, light, OverlayTexture.NO_OVERLAY, 1, 1, 1, 1);

			buffer = buffers.getBuffer(model.renderType(item.getCloakGlowTexture()));
			model.renderToBuffer(ms, buffer, 0xF000F0, OverlayTexture.NO_OVERLAY, 1, 1, 1, 1);
		}

public void tick(Level level) {
        if (this.previousPosition == null) {
            this.previousPosition = this.getAdjustedPosition();
        }
        Vec3 pos = getAdjustedPosition();

        Vec2 adjustedRotation = getAdjustedRotation();
        particleOptions.map.set(ParticlePropertyRegistry.EMITTER_PROPERTY.get(), new EmitterProperty(new Vec2(adjustedRotation.x, adjustedRotation.y), age));
        if (level instanceof ServerLevel serverLevel) {
            Networking.sendToNearbyClient(serverLevel, BlockPos.containing(pos), new TickEmitterPacket(this));
        } else {
            particleConfig.tick(particleOptions, level, pos.x, pos.y, pos.z, previousPosition.x, previousPosition.y, previousPosition.z);
        }
        this.previousPosition = pos;
        this.age++;
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        ParticleDensityProperty densityProp = getDensity(particleOptions, 100, 0.1f);
        SpeedProperty speedProperty = getSpeed(particleOptions);
        double minXSpeed = speedProperty.minXZ() * 0.25f;
        double minYSpeed = speedProperty.minY() * 0.25f;
        double maxXSpeed = speedProperty.maxXZ() * 0.25f;
        double maxYSpeed = speedProperty.maxY() * 0.25f;

        int density = densityProp.density();
        double radius = densityProp.radius();
        SpawnType spawnType = densityProp.spawnType().orElse(SpawnType.SPHERE);

        int totalParticles = getNumParticles(density);
        double deltaX = x - prevX;
        double deltaY = y - prevY;
        double deltaZ = z - prevZ;
        for (int i = 0; i < totalParticles; i++) {
            double t = (double) i / Math.max(1, totalParticles - 1);
            double px = prevX + deltaX * t;
            double py = prevY + deltaY * t;
            double pz = prevZ + deltaZ * t;
            Vec3 deltaVec = new Vec3(px, py, pz);
            Vec3 point = getMotionScaled(deltaVec, radius, spawnType);
            level.addAlwaysVisibleParticle(
                    particleOptions,
                    true,
                    point.x,
                    point.y,
                    point.z,
                    ParticleUtil.inRange(minXSpeed, maxXSpeed),
                    ParticleUtil.inRange(minYSpeed, maxYSpeed),
                    ParticleUtil.inRange(minXSpeed, maxXSpeed));
        }
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        int age = emitter.age;
        if (age == 0)
            return;
        ParticleDensityProperty density = getDensity(particleOptions, 100, 0.3f);
        int totalParticles = getNumParticles(density.density());
        float randomScale = 0.00f;
        double radius = density.radius();
        for (int step = 0; step <= totalParticles; step++) {
            double t = (double) step / totalParticles;
            double interpolatedX = prevX + t * (x - prevX);
            double interpolatedY = prevY + t * (y - prevY);
            double interpolatedZ = prevZ + t * (z - prevZ);
            double motionProgress = age + t;
            Vec3 local = getZigzag3D(motionProgress, 8, radius, 12, radius - radius * 0.3, 0.1);
            Vector3f transformed = toEmitterSpace((float) interpolatedX, (float) interpolatedY, (float) interpolatedZ,
                    (float) local.x(), (float) local.y(), (float) local.z);

            level.addParticle(particleOptions, transformed.x, transformed.y, transformed.z,
                    ParticleUtil.inRange(-randomScale, randomScale),
                    ParticleUtil.inRange(-randomScale, randomScale),
                    ParticleUtil.inRange(-randomScale, randomScale));
        }
    }

public void playParticles() {
        if (tickEmitter == null && resolver() != null) {
            buildEmitters();
        }
        if (this.tickEmitter != null) {
            this.tickEmitter.tick(level);
        }

        if (flairEmitter != null) {
            this.flairEmitter.tick(level);
        }

        if (!playedSpawnParticle && onSpawnEmitter != null) {
            this.onSpawnEmitter.tick(level);
            playedSpawnParticle = true;
        }
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        WallProperty wallProperty = particleOptions.map.getOrDefault(ParticlePropertyRegistry.WALL_PROPERTY.get(), new WallProperty(5, 5, 20, Direction.NORTH));
        ParticleDensityProperty density = getDensity(particleOptions, 20, 0.0f);
        RandomSource rand = level.random;
        int chance = wallProperty.chance;
        int range = wallProperty.range;
        double growthFactor = 1.0f;
        Direction direction = wallProperty.direction;

        BlockPos pos = BlockPos.containing(x, y, z);

        BlockPos.betweenClosedStream(pos.offset(range * direction.getStepX(), 0, range * direction.getStepZ()), pos.offset(-range * direction.getStepX(), range, -range * direction.getStepZ())).forEach(blockPos -> {
            if (rand.nextInt(chance) == 0) {
                for (int i = 0; i < getNumParticles(density.density()); i++) {
                    double dx = blockPos.getX() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    double dy = blockPos.getY() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    double dz = blockPos.getZ() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    level.addAlwaysVisibleParticle(particleOptions,
                            true,
                            dx, dy, dz,
                            0, ParticleUtil.inRange(0.01, 0.08), 0);
                }
            }
        });
    }

public void castSpells() {
        float aoe = getAoe();
        int flatAoe = Math.round(aoe);
        BlockPos start = blockPosition().offset(flatAoe * getDirection().getStepX(), 0, flatAoe * getDirection().getStepZ());
        BlockPos end = blockPosition().offset(-flatAoe * getDirection().getStepX(), flatAoe, -flatAoe * getDirection().getStepZ());
        if (isSensitive()) {
            if (age % (Math.max(1, 20 - 2 * getAccelerates())) != 0 && age != 1)
                return;
            for (BlockPos p : BlockPos.betweenClosed(start, end)) {
                p = p.immutable();
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new
                            BlockHitResult(new Vec3(p.getX(), p.getY(), p.getZ()), Direction.UP, p, false));
                }
                resolveEmitter.setPositionOffset(p.subtract(blockPosition()).getCenter());
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
            }
            if (!level.isClientSide) {
                resolveSound.playSound(level, getX(), getY(), getZ());
            }
        } else {
            int i = 0;
            // Expand the axis if start and end are equal

            AABB aabb = AABB.encapsulatingFullBlocks(start, end);
            if (aabb.maxX == aabb.minX) {
                aabb = aabb.inflate(growthFactor, 0, 0);
            }
            if (aabb.maxY == aabb.minY) {
                aabb = aabb.inflate(0, growthFactor, 0);
            }
            if (aabb.maxZ == aabb.minZ) {
                aabb = aabb.inflate(0, 0, growthFactor);
            }
            for (Entity entity : level.getEntities(null, aabb)) {
                if (entity.equals(this) || entity.getType().is(EntityTags.LINGERING_BLACKLIST)) {
                    continue;
                }
                Optional<EntityHit> hit = hitEntities.stream().filter(e -> e.entity.refersTo(entity)).findFirst();
                boolean skipEntity = hit.isPresent();
                if (hit.isPresent() && level.getGameTime() - hit.get().gameTime > 20) {
                    hitEntities.remove(hit.get());
                    skipEntity = false;
                }
                if (skipEntity)
                    continue;
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new EntityHitResult(entity));
                }
                resolveEmitter.setPositionOffset(entity.position.subtract(position).add(0, entity.getBbHeight() / 2.0, 0));
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
                i++;
                if (hit.isEmpty()) {
                    hitEntities.add(new EntityHit(entity));
                }
                if (i > 5)
                    break;
                if (!level.isClientSide) {
                    resolveSound.playSound(level, getX(), getY(), getZ());
                }
            }
            totalProcs += i;
            if (totalProcs >= maxProcs)
                this.remove(RemovalReason.DISCARDED);
        }
    }

private static void renderNode(StarsEdgeConstellationVisualEntity entity, VertexConsumer vertices,
                                   MatrixStack matrices, float age, float phaseAge, float alpha) {
        float grow = easeOut(MathHelper.clamp(age / 7.0F, 0.0F, 1.0F));
        float detonationProgress = MathHelper.clamp(phaseAge / 5.0F, 0.0F, 1.0F);
        float phasePulse = entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_DETONATE
                ? (1.0F + 1.15F * MathHelper.sin(detonationProgress * MathHelper.PI))
                * (1.0F - detonationProgress * 0.35F)
                : entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED
                ? 1.0F + 0.12F * MathHelper.sin(phaseAge * 0.38F)
                : 1.0F + 0.06F * MathHelper.sin(age * 0.22F);
        float scale = grow * phasePulse;

        matrices.translate(0.0, 0.88 + MathHelper.sin(age * 0.10F) * 0.06F, 0.0);
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(age * 2.8F));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(age * 1.35F));
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.42F * scale, 0.20F * scale,
                104, 35, 224, alpha(118, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.42F * scale, 0.20F * scale,
                104, 35, 224, alpha(105, alpha), FULL_LIGHT);
        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.29F * scale, 0.125F * scale,
                65, 230, 255, alpha(220, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.29F * scale, 0.125F * scale,
                65, 230, 255, alpha(205, alpha), FULL_LIGHT);
        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.13F * scale, 0.07F * scale,
                246, 250, 255, alpha(255, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.13F * scale, 0.07F * scale,
                246, 250, 255, alpha(245, alpha), FULL_LIGHT);

        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(-age * 3.4F));
        drawRing(vertices, matrices.peek().getPositionMatrix(), 0.52F * grow,
                0.018F, 81, 208, 255, alpha(150, alpha), FULL_LIGHT);
    }

private static void renderLink(StarsEdgeConstellationVisualEntity entity, VertexConsumer vertices,
                                   Matrix4f matrix, float age, float phaseAge, float alpha) {
        Vec3d start = new Vec3d(0.0, 0.88, 0.0);
        Vec3d offset = entity.getEndOffset();
        float grow = easeOut(MathHelper.clamp(age / 8.0F, 0.0F, 1.0F));
        Vec3d end = start.add(offset.multiply(grow));
        if (start.squaredDistanceTo(end) < 0.0001) {
            return;
        }

        float detonationProgress = MathHelper.clamp(phaseAge / 5.0F, 0.0F, 1.0F);
        float pulse = entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_DETONATE
                ? 1.0F + 2.1F * MathHelper.sin(detonationProgress * MathHelper.PI)
                : entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED
                ? 1.0F + 0.16F * MathHelper.sin(phaseAge * 0.45F)
                : 1.0F;
        drawCrossRibbon(vertices, matrix, start, end, 0.105F * pulse,
                91, 30, 205, alpha(105, alpha), FULL_LIGHT);
        drawCrossRibbon(vertices, matrix, start, end, 0.048F * pulse,
                63, 222, 255, alpha(205, alpha), FULL_LIGHT);
        drawCrossRibbon(vertices, matrix, start, end, 0.017F * pulse,
                244, 249, 255, alpha(245, alpha), FULL_LIGHT);

        int moteCount = Math.max(1, Math.min(4, (int) Math.ceil(offset.length() / 2.0)));
        for (int i = 0; i < moteCount; i++) {
            double progress = positiveModulo(age * 0.045F + i / (double) moteCount, 1.0);
            if (entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED) {
                progress = positiveModulo(phaseAge * 0.075F + i / (double) moteCount, 1.0);
            }
            Vec3d mote = start.lerp(end, progress);
            float motePulse = 0.07F + 0.025F * MathHelper.sin(age * 0.4F + i * 1.7F);
            drawTinyStar(vertices, matrix, mote, motePulse,
                    226, 245, 255, alpha(235, alpha), FULL_LIGHT);
        }
    }

@Override
    public void render(T entity, float yaw, float tickDelta, MatrixStack matrices,
                       VertexConsumerProvider vertexConsumers, int light) {
        float progress = entity.getProgress();
        if (progress <= 0.0F) {
            return;
        }

        float age = entity.age + tickDelta;
        Entity owner = resolveOwner(entity);

        Vec3d offset = Vec3d.ZERO;
        float lookYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevYaw, entity.getYaw());
        float lookPitch = 0.0F;
        float height = 1.2F;
        if (owner != null) {
            Vec3d ownerPos = new Vec3d(
                    MathHelper.lerp(tickDelta, owner.prevX, owner.getX()),
                    MathHelper.lerp(tickDelta, owner.prevY, owner.getY()),
                    MathHelper.lerp(tickDelta, owner.prevZ, owner.getZ()));
            Vec3d selfPos = new Vec3d(
                    MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                    MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                    MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
            offset = ownerPos.subtract(selfPos);
            height = owner.getHeight() * CHEST_HEIGHT_FRACTION;
            lookYaw = MathHelper.lerpAngleDegrees(tickDelta, owner.prevYaw, owner.getYaw());
            lookPitch = MathHelper.lerp(tickDelta, owner.prevPitch, owner.getPitch());
        }

        matrices.push();
        matrices.translate(offset.x, offset.y + height, offset.z);
        // Local -Z follows the owner's look direction.
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F - lookYaw));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(-lookPitch));
        matrices.translate(0.0F, 0.0F, -FORWARD_OFFSET);

        ParchmentRendering.renderGlyphArc(matrices, vertexConsumers, entity.getGlyphStyleId(),
                entity.getGlyphBase(), entity.getGlyphCount(), progress, age, 1.35F);
        matrices.pop();

        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private static void renderEncasement(WaxweaverWaxVisualEntity visual, MatrixStack matrices,
                                          VertexConsumerProvider providers, Sprite bone, Sprite honey,
                                          Sprite magma, float time, float tickDelta, int light) {
        Entity entity = visual.getWorld().getEntityById(visual.getTargetId());
        if (!(entity instanceof LivingEntity target)) return;

        MinecraftClient client = MinecraftClient.getInstance();
        if (target == client.player && client.options.getPerspective().isFirstPerson()) return;

        Vec3d correction = lerped(target, tickDelta).subtract(lerped(visual, tickDelta));
        matrices.translate(correction.x, correction.y, correction.z);

        float fullHeight = Math.max(0.62F, target.getHeight() + 0.28F);
        float baseRadius = Math.max(0.58F, target.getWidth() * 0.72F + 0.23F);
        float formation = smooth(MathHelper.clamp(time / WaxweaverEncasementManager.FORMATION_TICKS, 0.0F, 1.0F));
        float shownHeight = Math.max(0.045F, fullHeight * formation);
        float remaining = visual.getLifetime() - time;
        float warning = smooth(MathHelper.clamp((20.0F - remaining) / 20.0F, 0.0F, 1.0F));
        float shudder = warning * warning * 0.025F;
        if (shudder > 0.0F) {
            matrices.translate(MathHelper.sin(time * 3.7F + visual.getSeed() * 0.013F) * shudder,
                    MathHelper.sin(time * 5.1F) * shudder * 0.35F,
                    MathHelper.cos(time * 4.3F + visual.getSeed() * 0.009F) * shudder);
        }

        int waxLight = Math.max(light, 0x00C000C0);
        VertexConsumer solid = providers.getBuffer(RenderLayer.getEntityCutout(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
        drawFootMound(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                MathHelper.clamp(time / 2.8F, 0.0F, 1.0F), waxLight);
        drawCoreShell(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                fullHeight, shownHeight, waxLight);
        drawLayeredPlates(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                fullHeight, time, waxLight);

        float seal = smooth(MathHelper.clamp((time - 7.2F) / 2.8F, 0.0F, 1.0F));
        if (seal > 0.0F) {
            drawHardenedDrips(solid, matrices, bone, visual.getSeed(), baseRadius,
                    fullHeight, seal, waxLight);
            drawWick(solid, matrices, bone, fullHeight, seal, waxLight);

            VertexConsumer translucent = providers.getBuffer(RenderLayer.getTranslucentMovingBlock());
            drawSeams(translucent, matrices, honey, visual.getSeed(), baseRadius,
                    fullHeight, seal, warning, Math.max(light, 0x00D000D0), false);
            if (warning > 0.025F) {
                VertexConsumer emissive = providers.getBuffer(
                        RenderLayer.getEntityTranslucentEmissive(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
                drawSeams(emissive, matrices, magma, visual.getSeed(), baseRadius,
                        fullHeight, seal, warning, FULL_LIGHT, true);
            }
        }
    }

@Override
    public void render(RiftmaneRiftVisualEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        if (IrisCompat.isRenderingShadowPass() || !Config.general.enableModernFieldEffects) {
            return;
        }

        float age = entity.age + tickDelta;
        float remaining = entity.getLifetime() - age;
        float open = RiftmaneRenderGeometry.easeOutBack(MathHelper.clamp(age / OPEN_TICKS, 0.0F, 1.0F));
        float close = MathHelper.clamp(remaining / CLOSE_TICKS, 0.0F, 1.0F);
        float widthScale = open * MathHelper.clamp(close * 1.7F, 0.0F, 1.0F);
        float heightScale = open * close;
        boolean lensVisible = widthScale >= 0.01F && heightScale >= 0.01F;
        float ringProgress = MathHelper.clamp(
                (age - (entity.getLifetime() - SLAM_RING_TICKS)) / SLAM_RING_TICKS, 0.0F, 1.0F);
        boolean ringVisible = ringProgress > 0.0F && ringProgress < 1.0F;
        if (!lensVisible && !ringVisible) {
            return;
        }

        float height = entity.getRiftHeight();
        double halfHeight = height * 0.5 * heightScale;
        double halfWidth = height * HALF_WIDTH_RATIO * widthScale;
        double centerY = height * 0.5;
        int seed = entity.getSeed();
        float wobblePhase = age * 0.35F + seed;

        matrices.push();
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-entity.getYaw()));
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        if (lensVisible) {
            VertexConsumer core = vertexConsumers.getBuffer(RenderLayer.getEntityTranslucent(WHITE_TEXTURE));
            RiftmaneRenderGeometry.lensFill(core, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    4, 8, 14, 235, 120);
        }

        VertexConsumer glow = vertexConsumers.getBuffer(RenderLayer.getEntityTranslucentEmissive(WHITE_TEXTURE));
        if (lensVisible) {
            RiftmaneRenderGeometry.lensRim(glow, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    0.14 + 0.05 * MathHelper.sin(wobblePhase * 1.7F), 0.45F, wobblePhase,
                    150, 255, 246, 230, 0);
            RiftmaneRenderGeometry.lensRim(glow, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    0.05, 0.2F, wobblePhase * 1.4F, 226, 255, 252, 255, 90);
            drawLightColumn(glow, matrix, height, halfWidth, heightScale, wobblePhase);
        }
        if (ringVisible) {
            drawSlamRing(glow, matrix, ringProgress);
        }

        if (lensVisible) {
            VertexConsumer arcs = vertexConsumers.getBuffer(LightningRenderLayers.BLOCKY_LIGHTNING);
            drawRimArcs(arcs, matrix, centerY, halfWidth, halfHeight, seed, age, heightScale);
        }

        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private void renderLeg(ItemStack legItem, LivingEntity entity, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, boolean glintIn, HumanoidModel modelIn, float red, float green, float blue, ResourceLocation armorResource, boolean notAVanillaModel) {
        VertexConsumer ivertexbuilder = ItemRenderer.getFoilBuffer(bufferIn, RenderType.entityCutoutNoCull(armorResource), false, glintIn);
        renderer.getModel().copyPropertiesTo(modelIn);
        modelIn.body.xRot = 0F;
        modelIn.body.yRot = 0;
        modelIn.body.zRot = 0;
        modelIn.body.x = 0;
        modelIn.body.y = 0F;
        modelIn.body.z = 0F;
        modelIn.rightLeg.x = 0F;
        modelIn.rightLeg.xRot = 0F;
        modelIn.rightLeg.yRot = 0F;
        modelIn.rightLeg.zRot = 0F;
        modelIn.leftLeg.x = 0F;
        modelIn.leftLeg.xRot = 0F;
        modelIn.leftLeg.yRot = 0F;
        modelIn.leftLeg.zRot = 0F;
        modelIn.leftLeg.y = 0F;
        modelIn.rightLeg.y = 0F;
        modelIn.leftLeg.z = 0F;
        modelIn.rightLeg.z = 0F;
        renderer.getModel().rightLegPartArmors().forEach(part -> {
            matrixStackIn.pushPose();
            renderer.getModel().translateToLeg(part, matrixStackIn);
            modelIn.rightLeg.render(matrixStackIn, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, red, green, blue, 1.0F);
