        if (MobsConfig.HierarchicalArmorTrim.get()) {
            ArmorTrim.getTrim(entity.level().registryAccess(), legItem).ifPresent(armorTrim -> {
                if (legItem.getItem() instanceof ArmorItem armorItem) {
                    TextureAtlasSprite sprite = this.armorTrimAtlas.getSprite(armorTrim.innerTexture(armorItem.getMaterial()));
                    renderer.getModel().rightLegPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToLeg(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.rightLeg.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                    renderer.getModel().leftLegPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToLeg(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.leftLeg.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                    renderer.getModel().bodyPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToChest(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.body.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                }
            });
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords,
          STATE state, boolean isBaby, ItemStack stack) {
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(state));
        boolean renderFoil = stack.hasFoil();

        if (!armorQuads.isEmpty()) {
            int tintColor = getColor(stack);
            for (Map.Entry<ModelPos, PartData> entry : armorQuads.entrySet()) {
                ModelPos modelPos = entry.getKey();
                poseStack.pushPose();
                modelPos.translate(baseModel, poseStack, state);
                if (isBaby) {
                    modelPos.scaleBaby(poseStack, state);
                }
                modelPos.translateModel(poseStack);
                entry.getValue().render(poseStack, nodeCollector, lightCoords, state.outlineColor, tintColor, renderFoil);
                poseStack.popPose();
            }
        }


        if (type == EquipmentSlot.CHEST) {
            UUID entityUUID = state.getRenderData(UUID_CONTEXT);
            if (entityUUID != null) {
                long gameTime = Minecraft.getInstance().level == null ? 0L : Minecraft.getInstance().level.getGameTime();
                BoltRenderer boltRenderer = boltRenderMap.computeIfAbsent(entityUUID, _ -> new BoltRenderer());
                if (IModuleHelper.INSTANCE.isEnabled(state.chestEquipment, MekanismModules.GRAVITATIONAL_MODULATING_UNIT)) {
                    boltRenderer.update(0, LEFT_GRAV_BOLT, gameTime, state.partialTick);
                    boltRenderer.update(1, RIGHT_GRAV_BOLT, gameTime, state.partialTick);
                }
                List<BoltRenderState> boltRenderStates = boltRenderer.collectBoltStates(gameTime, state.partialTick);
                if (!boltRenderStates.isEmpty()) {
                    //Adjust the poseStack so that we render the lightning in the correct spot if the player is crouching
                    poseStack.pushPose();
                    ModelPos.BODY.translate(baseModel, poseStack, state);
                    PoseStack.Pose pose = poseStack.last().copy();
                    for (BoltRenderState boltState : boltRenderStates) {
                        nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltState));
                    }
                    poseStack.popPose();
                }
            }
        }
    }

public QuickHash key(HumanoidRenderState state) {
        Object2BooleanMap<ModuleModelSpec> modules = new Object2BooleanOpenHashMap<>();
        Set<EquipmentSlot> wornParts = EnumSet.noneOf(EquipmentSlot.class);
        for (EquipmentSlot slotType : EquipmentSlotGroup.ARMOR) {
            ItemStack stack = getItemBySlot(state, slotType);
            if (stack.getItem() instanceof ItemMekaSuitArmor) {
                IModuleContainer container = IModuleHelper.INSTANCE.getModuleContainer(stack);
                if (container != null) {
                    wornParts.add(slotType);
                    for (Entry<Holder<ModuleData<?>>, ModuleModelSpec> entry : moduleModelSpec.row(slotType).entrySet()) {
                        if (container.hasEnabled(entry.getKey())) {
                            ModuleModelSpec spec = entry.getValue();
                            modules.put(spec, spec.isActive(state));
                        }
                    }
                }
            }
        }
        return new QuickHash(modules.isEmpty() ? Object2BooleanMaps.emptyMap() : modules, wornParts.isEmpty() ? Collections.emptySet() : wornParts,
              getItemBySlot(state, state.mainArm == HumanoidArm.LEFT ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND).getItem() instanceof ItemMekaTool,
              getItemBySlot(state, state.mainArm == HumanoidArm.RIGHT ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND).getItem() instanceof ItemMekaTool);
    }

private static void drawWoundEnergy(VertexConsumer vertices, Matrix4f matrix, float age,
                                        long seed, int index, int count, float height,
                                        float radius, float bodyYaw, int primaryColor, int coreColor) {
        float angle = woundAngle(seed, index, count, bodyYaw);
        Vec3d outward = new Vec3d(MathHelper.sin(angle), 0.0, MathHelper.cos(angle));
        Vec3d tangent = new Vec3d(outward.z, 0.0, -outward.x);
        float tilt = woundTilt(seed, index);
        Vec3d longAxis = tangent.multiply(MathHelper.cos(tilt)).add(UP.multiply(MathHelper.sin(tilt)));
        Vec3d shortAxis = UP.multiply(MathHelper.cos(tilt)).subtract(tangent.multiply(MathHelper.sin(tilt)));
        float halfLength = woundHalfLength(seed, index, height);
        float halfWidth = woundHalfWidth(seed, index, halfLength);
        Vec3d center = woundCenter(seed, index, height, radius, outward).add(outward.multiply(0.018F));
        float pulse = 0.86F + MathHelper.sin(age * 0.16F + index * 1.73F) * 0.12F;
        int purple = scaleColor(primaryColor, 1.9F);
        int paleCore = mixColor(coreColor, 0xFFFFFF, 0.34F);
        for (int segment = 0; segment < 3; segment++) {
            Vec3d start = woundCorePoint(seed, index, segment, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            Vec3d end = woundCorePoint(seed, index, segment + 1, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            float taper = 1.0F - Math.abs(segment - 1) * 0.14F;
            woundGlowRibbon(vertices, matrix, start, end, shortAxis,
                    halfWidth * 0.21F * taper, outward, purple, Math.round(184.0F * pulse));
            woundGlowRibbon(vertices, matrix, start.add(outward.multiply(0.002F)),
                    end.add(outward.multiply(0.002F)), shortAxis,
                    halfWidth * 0.085F * taper, outward,
                    segment == 1 ? paleCore : coreColor, Math.round(242.0F * pulse));
        }
        for (int branch = 0; branch < 2; branch++) {
            int sample = branch + 1;
            Vec3d start = woundCorePoint(seed, index, sample, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            float direction = branch == 0 ? -1.0F : 1.0F;
            Vec3d end = start.add(shortAxis.multiply(direction * halfWidth * 0.6F))
                    .add(longAxis.multiply((BoltPath.unit(seed + index * 181L, branch, 67L) - 0.5F)
                            * halfLength * 0.32F));
            woundGlowRibbon(vertices, matrix, start, end, longAxis,
                    Math.max(0.005F, halfWidth * 0.035F), outward,
                    branch == 0 ? purple : coreColor, Math.round(174.0F * pulse));
        }
    }

private static void drawGloamTendril(
            VertexConsumer vertices, Matrix4f matrix,
            Vec3d start, Vec3d end, float age, long seed,
            float reveal, int color, int alpha) {
        Vec3d span = end.subtract(start);
        if (span.lengthSquared() < 0.0001 || reveal <= 0.0F || alpha <= 0) {
            return;
        }
        Vec3d side = horizontalPerpendicular(span);
        double curlAmplitude = Math.min(0.18, 0.055 + span.length() * 0.025);
        Vec3d previous = start;
        float previousWidth = 0.085F;
        for (int segment = 1; segment <= 4; segment++) {
            float visible = MathHelper.clamp(reveal * 4.0F - segment + 1.0F, 0.0F, 1.0F);
            if (visible <= 0.0F) {
                break;
            }
            float progress = segment / 4.0F;
            float curl = (float) (MathHelper.sin(age * 0.065F + segment * 0.74F
                    + (float) BoltPath.unit(seed, segment, 347L) * 2.0F)
                    * curlAmplitude * MathHelper.sin(progress * MathHelper.PI));
            Vec3d fullNext = start.lerp(end, progress)
                    .add(side.multiply(curl))
                    .add(0.0, MathHelper.sin(progress * MathHelper.PI) * 0.055, 0.0);
            Vec3d next = previous.lerp(fullNext, visible);
            float nextWidth = MathHelper.lerp(progress, 0.085F, 0.025F);
            nextWidth = MathHelper.lerp(visible, previousWidth, nextWidth);
            Vec3d previousOffset = side.multiply(previousWidth);
            Vec3d nextOffset = side.multiply(nextWidth);
            woundColorQuad(vertices, matrix,
                    previous.add(previousOffset), previous.subtract(previousOffset),
                    next.subtract(nextOffset), next.add(nextOffset), color, alpha);
            woundColorQuad(vertices, matrix,
                    next.add(nextOffset), next.subtract(nextOffset),
                    previous.subtract(previousOffset), previous.add(previousOffset), color, alpha);
            Vec3d direction = next.subtract(previous);
            Vec3d cross = direction.lengthSquared() < 0.0001
                    ? UP
                    : direction.normalize().crossProduct(side).normalize();
            Vec3d previousCross = cross.multiply(previousWidth * 0.68F);
            Vec3d nextCross = cross.multiply(nextWidth * 0.68F);
            woundColorQuad(vertices, matrix,
                    previous.add(previousCross), previous.subtract(previousCross),
                    next.subtract(nextCross), next.add(nextCross), color, alpha);
            woundColorQuad(vertices, matrix,
                    next.add(nextCross), next.subtract(nextCross),
                    previous.subtract(previousCross), previous.add(previousCross), color, alpha);
            previous = next;
            previousWidth = nextWidth;
            if (visible < 1.0F) {
                break;
            }
        }
    }

private Map<ModelPos, PartData> createQuads(Object2BooleanMap<ModuleModelSpec> modules, Set<EquipmentSlot> wornParts, boolean hasMekaToolLeft, boolean hasMekaToolRight) {
        Map<OBJModelData, Map<ModelPos, Set<String>>> specialQuadsToRender = new Object2ObjectOpenHashMap<>();
        // map of normal model part name to overwritten model part name (i.e. helmet_head_center1 -> override_solar_helmet_helmet_head_center1)
        Map<String, OverrideData> overrides = new Object2ObjectOpenHashMap<>();
        Set<String> ignored = new HashSet<>();

        if (!modules.isEmpty()) {
            Map<OBJModelData, Set<String>> allMatchedParts = new Object2ObjectOpenHashMap<>();
            for (ModuleOBJModelData modelData : MekanismModelCache.INSTANCE.MEKASUIT_MODULES) {
                Set<String> matchedParts = allMatchedParts.computeIfAbsent(modelData, _ -> new HashSet<>());
                for (ObjectIterator<Object2BooleanMap.Entry<ModuleModelSpec>> iterator = Object2BooleanMaps.fastIterator(modules); iterator.hasNext(); ) {
                    Object2BooleanMap.Entry<ModuleModelSpec> entry = iterator.next();
                    ModuleModelSpec spec = entry.getKey();
                    for (String name : modelData.getPartsForSpec(spec, entry.getBooleanValue())) {
                        if (name.contains(OVERRIDDEN_TAG)) {
                            overrides.put(spec.processOverrideName(name), new OverrideData(modelData, name));
                        }
                        // if this armor unit controls rendering of this module
                        if (type == spec.slotType) {
                            // then add the part as one we will need to add to render, this way we can ensure
                            // we respect any overrides that might be in a later model part
                            matchedParts.add(name);
                        }
                    }
                }
            }
            for (Map.Entry<OBJModelData, Set<String>> entry : allMatchedParts.entrySet()) {
                Set<String> matchedParts = entry.getValue();
                if (!matchedParts.isEmpty()) {
                    OBJModelData modelData = entry.getKey();
                    Map<ModelPos, Set<String>> quadsToRender = specialQuadsToRender.computeIfAbsent(modelData, _ -> new EnumMap<>(ModelPos.class));
                    //For all the parts we matched, go through and try adding them, while respecting any overrides we might have
                    for (String name : matchedParts) {
                        ModelPos pos = ModelPos.get(name);
                        if (pos == null) {
                            Mekanism.logger.warn("MekaSuit part '{}' is invalid from modules model. Ignoring.", name);
                        } else {
                            //Note: Currently the special quads here for overrides will likely point to our module quads to render
                            // but for consistency and future proofing it is better to make sure we look it up in case overrides gets other stuff
                            // added to it at some point
                            addQuadsToRender(pos, name, overrides, quadsToRender, specialQuadsToRender);
                        }
                    }
                }
            }
        }

        // handle mekatool overrides
        if (type == EquipmentSlot.CHEST) {
            if (hasMekaToolLeft) {
                ignored.addAll(MekanismModelCache.INSTANCE.getOverrideMekaToolParts(true));
            }
            if (hasMekaToolRight) {
                ignored.addAll(MekanismModelCache.INSTANCE.getOverrideMekaToolParts(false));
            }
        }

        Map<ModelPos, Set<String>> armorQuadsToRender = new EnumMap<>(ModelPos.class);
        for (String name : MekanismModelCache.INSTANCE.MEKASUIT.getPartNames()) {
            if (!checkEquipment(type, name)) {
                // skip if it's the wrong equipment type
                continue;
            } else if (name.startsWith(EXCLUSIVE_TAG)) {
                if (wornParts.contains(adjacentType)) {
                    // skip if the part is exclusive and the adjacent part is present
                    continue;
                }
            } else if (name.startsWith(SHARED_TAG) && wornParts.contains(adjacentType) && adjacentType.ordinal() > type.ordinal()) {
                // skip if the part is shared and the shared part already rendered
                continue;
            }
            ModelPos pos = ModelPos.get(name);
            if (pos == null) {
                Mekanism.logger.warn("MekaSuit part '{}' is invalid. Ignoring.", name);
            } else if (!ignored.contains(name)) {
                addQuadsToRender(pos, name, overrides, armorQuadsToRender, specialQuadsToRender);
            }
        }

        Map<ModelPos, PartData> armorQuads = new EnumMap<>(ModelPos.class);
        for (ModelPos pos : ModelPos.VALUES) {
            for (OBJModelData modelData : MekanismModelCache.INSTANCE.MEKASUIT_MODULES) {
                parseTransparency(modelData, pos, armorQuads, specialQuadsToRender.getOrDefault(modelData, Collections.emptyMap()));
            }
            parseTransparency(MekanismModelCache.INSTANCE.MEKASUIT, pos, armorQuads, armorQuadsToRender);
        }
        return armorQuads.isEmpty() ? Collections.emptyMap() : armorQuads;
    }

private static void parseTransparency(OBJModelData modelData, ModelPos pos, Map<ModelPos, PartData> armorQuads, Map<ModelPos, Set<String>> regularQuads) {
        Set<String> allQuads = regularQuads.getOrDefault(pos, Collections.emptySet());
        if (!allQuads.isEmpty()) {
            Set<String> opaqueQuads = new HashSet<>();
            Set<String> opaqueEmissiveQuads = new HashSet<>();
            Set<String> translucentQuads = new HashSet<>();
            PartData partData = armorQuads.computeIfAbsent(pos, _ -> new PartData());
            for (String quad : allQuads) {
                if (quad.contains(GLASS_TAG)) {
                    translucentQuads.add(quad);
                } else if (quad.contains(EMISSIVE_TAG)) {
                    opaqueEmissiveQuads.add(quad);
                } else {
                    opaqueQuads.add(quad);
                }
            }
            //Only add a new entry to our map if we will have any parts. Our getParts method will return empty if there are no quads
            List<BlockStateModelPart> opaqueParts = modelData.getParts(opaqueQuads);
            List<BlockStateModelPart> opaqueEmissiveParts = modelData.getParts(opaqueEmissiveQuads);
            List<BlockStateModelPart> translucentParts = modelData.getParts(translucentQuads);
            if (!opaqueParts.isEmpty()) {
                partData.opaque().addAll(opaqueParts);
            }
            if (!opaqueEmissiveParts.isEmpty()) {
                partData.emissive().addAll(opaqueEmissiveParts);
            }
            if (!translucentParts.isEmpty()) {
                partData.translucent().addAll(translucentParts);
            }
        }
    }

private void submitModel(OrderedSubmitNodeCollector orderedCollector, PoseStack poseStack, List<BlockStateModelPart> parts, int lightCoords, int outlineColor,
              int tintColor, RenderType noTint, RenderType withTint) {
            if (tintColor == CommonColors.WHITE || ARGB.alpha(tintColor) == 0) {
                //If it is white or fully transparent, just render it without tint
                orderedCollector.submitBlockModel(poseStack, noTint, parts, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                return;
            }
            //Based on submitBlockModel, but using a custom render type and passing a tint color
            PoseStack.Pose pose = poseStack.last().copy();
            if (!withTint.isOutline()) {
                BlockModelFeatureRenderer.Submit submit = new BlockModelFeatureRenderer.Submit(pose, withTint, parts, BlockModelRenderState.EMPTY_TINTS, lightCoords,
                      OverlayTexture.NO_OVERLAY, tintColor, null);
                if (withTint.hasBlending()) {
                    orderedCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_BLOCKS_AND_ITEMS, submit);
                } else {
                    orderedCollector.submitSpecial(RenderPhaseKeys.SOLID, submit);
                }
            }
            if (outlineColor != 0) {
                //Note: We don't need to color
                RenderType outlineRenderType = noTint.outline().isPresent() ? noTint.outline().get() : null;
                if (outlineRenderType != null) {
                    orderedCollector.submitSpecial(RenderPhaseKeys.OUTLINE, new BlockModelFeatureRenderer.Submit(pose, outlineRenderType, parts,
                          BlockModelRenderState.EMPTY_TINTS, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, outlineColor, null));
                }
            }
        }

protected void renderArmorPiece(PoseStack poseStack, MultiBufferSource bufferSource, T livingEntity, EquipmentSlot slot, int packedLight, A baseModel, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
    ItemStack itemstack = livingEntity.getItemBySlot(slot);

    if (itemstack.getItem() instanceof ArmorItem armoritem) {
        if (armoritem.getEquipmentSlot() == slot) {
            Model model = getArmorModelHook(livingEntity, itemstack, slot, baseModel);

            if (!(model instanceof HumanoidModel<?>)) {
                return;
            }

            getParentModel().copyPropertiesTo(baseModel);
            getParentModel().copyPropertiesTo((HumanoidModel<T>) model);

            setPartVisibility(baseModel, slot);
            setPartVisibility((A) model, slot);

            boolean usesInnerModel = usesInnerModel(slot);
            ArmorMaterial armormaterial = armoritem.getMaterial().value();

            IClientItemExtensions extensions = IClientItemExtensions.of(itemstack);
            extensions.setupModelAnimations(livingEntity, itemstack, slot, model, limbSwing, limbSwingAmount, partialTick, ageInTicks, netHeadYaw, headPitch);
            int fallbackColor = extensions.getDefaultDyeColor(itemstack);
            ModelBipedAnimated.setUseMatrixMode(baseModel, true);

            for (int layerIdx = 0; layerIdx < armormaterial.layers().size(); layerIdx++) {
                ArmorMaterial.Layer armormaterial$layer = armormaterial.layers().get(layerIdx);
                int tintColor = extensions.getArmorLayerTintColor(itemstack, livingEntity, armormaterial$layer, layerIdx, fallbackColor);

                if (tintColor != 0) {
                    ResourceLocation texture = ClientHooks.getArmorTexture(livingEntity, itemstack, armormaterial$layer, usesInnerModel, slot);
                    renderModel(poseStack, bufferSource, packedLight, model, tintColor, texture);
                }
            }

            ArmorTrim armortrim = itemstack.get(DataComponents.TRIM);

            if (armortrim != null) {
                ModelBipedAnimated.setUseMatrixMode(baseModel, true);
                ((HumanoidArmorLayerAccess) this).mowziesmobs$renderTrim(armoritem.getMaterial(), poseStack, bufferSource, packedLight, armortrim, model, usesInnerModel);
            }

            if (itemstack.hasFoil()) {
                ModelBipedAnimated.setUseMatrixMode(baseModel, true);
                ((HumanoidArmorLayerAccess) this).mowziesmobs$renderGlint(poseStack, bufferSource, packedLight, model);
            }
        }
    }
}

@Override
    public @NotNull VertexConsumer setUv(float u, float v) {

        float v0 = sprite.getV0();
        float v1 = sprite.getV1();
        float delta = (v - v0) / (v1 - v0);
        if (isInner) {
            delta -= 0.25f;
        }
        delta *= 2f;
        v = Mth.lerp(delta, v0, v1);

        return super.setUv(u, v);
    }

private void followTarget() {
        var target = getFollowedTarget();
        var data = projectileData();
        if (data == null) {
            return;
        }
        var homing_angle = projectileData().homing_angle;
        if (projectileData().homing_angles != null && followTicks < projectileData().homing_angles.length) {
            homing_angle = projectileData().homing_angles[followTicks];
        }
        if (target != null && homing_angle > 0) {
            if (data.homing_after_relative_distance > 0 || data.homing_after_absolute_distance > 0) {
                var shouldFollow = distanceTraveled >= (distanceToFollow * data.homing_after_relative_distance)
                        || distanceTraveled >= data.homing_after_absolute_distance;
                if (!shouldFollow) {
                    return;
                }
            }
//            System.out.println((this.getWorld().isClient ? "Client: " : "Server: ") + "Following target: " + target + " with angle: " + homing_angle);
            var distanceVector = (target.getPos().add(0, target.getHeight() / 2F, 0))
                    .subtract(this.getPos().add(0, this.getHeight() / 2F, 0));
//            System.out.println((world.isClient ? "Client: " : "Server: ") + "Distance: " + distanceVector);
//            System.out.println((world.isClient ? "Client: " : "Server: ") + "Velocity: " + getVelocity());
            var newVelocity = VectorHelper.rotateTowards(getVelocity(), distanceVector, homing_angle);
            if (newVelocity.lengthSquared() > 0) {
//                System.out.println((world.isClient ? "Client: " : "Server: ") + "Rotated to: " + newVelocity);
                this.setVelocity(newVelocity);
                // this.velocityDirty = true;
                followTicks += 1;
            }
        }
    }

