        this.renderRotatedParticle(p_233985_, p_233986_, p_233987_, (p_234005_) -> {
            p_234005_.mul(new Quaternionf()).rotationX(-MathHelper.modelDegrees(90));
        });
        this.renderRotatedParticle(p_233985_, p_233986_, p_233987_, (p_234000_) -> {
