private static void renderShieldingLine(Purpoid purpoid, float partialTicks, PoseStack stack, MultiBufferSource bufferSource, Vec3 mommyPos, int stunTimer) {
		stack.pushPose();
		double interpolatedPurpoidX = Mth.lerp(partialTicks, purpoid.xo, purpoid.getX());
		double interpolatedPurpoidY = Mth.lerp(partialTicks, purpoid.yo, purpoid.getY()) + 0.25F;
		double interpolatedPurpoidZ = Mth.lerp(partialTicks, purpoid.zo, purpoid.getZ());
		stack.translate(0.0F, 0.25F, 0.0F);
		float xDifference = (float) (mommyPos.x - interpolatedPurpoidX);
		float yDifference = (float) (mommyPos.y + 1.0F - interpolatedPurpoidY);
		float zDifference = (float) (mommyPos.z - interpolatedPurpoidZ);
		VertexConsumer vertexconsumer = bufferSource.getBuffer(EERenderTypes.PURPAZOID_SHIELDING_LINE);
		Matrix4f matrix4f = stack.last().pose();
		float width = 0.1F;
		float widthProportionalToDistance = (float) Mth.fastInvSqrt(xDifference * xDifference + zDifference * zDifference) * width / 2.0F;
		float zGap = zDifference * widthProportionalToDistance;
		float xGap = xDifference * widthProportionalToDistance;

		float stunTimerHalfCycles = Math.max(stunTimer - partialTicks, 0.0F) / 20.0F;
		float alpha = 0.1F + 0.4F * (1.0F - 2.0F * Mth.abs(stunTimerHalfCycles - Mth.floor(stunTimerHalfCycles + 0.5F)));

		float baseR = 0.643F;
		float baseG = 0.482F;
		float baseB = 0.918F;
		if (purpoid.hurtTime > 0 || purpoid.deathTime > 0) {
			baseR = baseR * 0.5F + 0.5F;
			baseG *= 0.5F;
			baseB *= 0.5F;
		}

		float waveOffset = Mth.PI * (purpoid.tickCount + partialTicks) / 20.0F;
		for (int i = 0; i <= 48; ++i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, width, zGap, xGap, i, false);
		}

		for (int i = 48; i >= 0; --i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, 0.0F, zGap, xGap, i, true);
		}

		stack.popPose();
	}

@Override
	public void render(PoseStack stack, MultiBufferSource bufferIn, int packedLightIn, Purpoid purpoid, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
		if (!purpoid.isBaby() || purpoid.getIDOfShieldedMommy() < 0) return;
		PurpoidModel model = this.purpazoidModel;
		model.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		PurpoidGelModel gelModel = this.gelModel;
		gelModel.parentToHead(model.head);
		gelModel.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		stack.pushPose();
		stack.translate(0.0F, 0.8125F, 0.0F);
		float inAndOut = 0.05F * Mth.abs(Mth.sin(0.15707963267F * ageInTicks));
		float scale = 0.5F + inAndOut;
		stack.scale(scale, scale, scale);
		float alpha = 0.15F + inAndOut;
		VertexConsumer nonEmissiveBuffer = bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidRenderer.getTexture(2)));
		model.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidEmissiveLayer.TEXTURES[2])), 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		stack.popPose();
	}

private void renderAgedSpans(AraTrailParticle particle, Matrix4f worldToTrail, float partialTicks, SpanVisitor visitor) {
        var config = particle.config;
        var points = particle.getPoints();

        // ---- per-frame tail smoothing (render-only, non-destructive; restored in finally) ----
        // The sim removes points at the 20 TPS tick, so the tail would pop a whole segment each 0.05s.
        // Here we "age" the trail by the current frame fraction so the tail recedes continuously between
        // ticks: (1) subtract the elapsed life from every point (the smoothness>1 spline then trims dying
        // sub-points via its life-cull, and segment-over-time tapers advance smoothly), and (2) for the
        // flat smoothness<=1 path, geometrically retract the oldest point toward the next as it dies so its
        // last segment shrinks to zero instead of vanishing. All reverted after the mesh build.
        float elapsedTicks = partialTicks * particle.emitter.timeScale();
        float ageAmt = elapsedTicks / 20f;   // life (seconds) elapsed since last tick
        if (savedLivesPool.length < points.size()) {
            savedLivesPool = new float[Math.max(points.size(), savedLivesPool.length * 2)];
        }
        float[] savedLives = savedLivesPool; // scoped to this trail: restored in the finally below
        for (int i = 0; i < points.size(); ++i) {
            savedLives[i] = points.get(i).life;
            points.get(i).life -= ageAmt;
        }
        // physics only steps at the tick: carry the points the elapsed fraction further so they don't hop at 20 Hz
        boolean extrapolated = elapsedTicks > 0 && particle.runtime.physics.isEnable();
        if (extrapolated) {
            if (savedPositionsPool.length < points.size() * 3) {
                savedPositionsPool = new float[Math.max(points.size() * 3, savedPositionsPool.length * 2)];
            }
            for (int i = 0; i < points.size(); ++i) {
                var position = points.get(i).position;
                savedPositionsPool[i * 3] = position.x;
                savedPositionsPool[i * 3 + 1] = position.y;
                savedPositionsPool[i * 3 + 2] = position.z;
            }
            particle.extrapolatePhysics(elapsedTicks);
        }
        Point tail = points.getFirst();
        Vector3f savedTail = null;
        if (config.smoothness <= 1 && !tail.discontinuous && tail.life < 0) {
            var next = points.get(1);
            float lerpDur = next.life - tail.life;   // segment life span (aging cancels in the difference)
            if (lerpDur > EPSILON) {
                float f = Mth.clamp(-tail.life / lerpDur, 0f, 1f);
                savedTail = new Vector3f(tail.position);
                tail.position = new Vector3f(savedTail).lerp(next.position, f);
            }
        }

        // Keep the head smooth between ticks: move the stored last point to the partial-tick-interpolated
        // emitter position for the mesh build only, then restore it so the tick sim never sees it (render
        // and tick are both on the client thread, sequential — no concurrent observation).
        Point head = (!particle.isRemoved() && config.emit && !points.getLast().discontinuous) ? points.getLast() : null;
        Vector3f savedHead = head == null ? null : new Vector3f(head.position);
        if (head != null) head.position = worldToTrail.transformPosition(particle.getWorldPosition());
        try {
            // get discontinuous point indices:
            discontinuities.clear();
            for (int i = 0; i < points.size(); ++i)
                if (points.get(i).discontinuous || i == points.size() - 1) discontinuities.add(i);

            // visit each trail segment span:
            int start = 0;
            for (int i = 0; i < discontinuities.size(); ++i) {
                visitor.visit(start, discontinuities.getInt(i));
                start = discontinuities.getInt(i) + 1;
            }
        } finally {
            for (int i = 0; i < points.size(); ++i) points.get(i).life = savedLives[i];
            if (savedTail != null) tail.position = savedTail;
            if (head != null) head.position = savedHead; // restore before any tick observes it
            if (extrapolated) {
                // by value and last: the tail/head restores above may have swapped the vector instances
                for (int i = 0; i < points.size(); ++i) {
                    points.get(i).position.set(savedPositionsPool[i * 3], savedPositionsPool[i * 3 + 1], savedPositionsPool[i * 3 + 2]);
                }
            }
        }
    }

