public BurrowingArrowEntity(Level level, LivingEntity shooter) {
        super(ACEntityRegistry.BURROWING_ARROW.get(), shooter, level);
        this.setBaseDamage(3.5D);
        this.setPierceLevel((byte)(this.getPierceLevel() + 1));
