	}

@Override
	public void writeCustomNBT(CompoundTag nbt, boolean descPacket, Provider provider)
	{
		nbt.put("shader", ShaderWrapper_Direct.SERIALIZER.write(shader, provider));
	}

@Override
	public boolean triggerEvent(int id, int arg)
