private static void renderCorruptedWounds(LivingEntity entity, float tickDelta,
                                               ObserverStatusVisualStyle style,
                                               MatrixStack matrices,
                                               VertexConsumerProvider consumers) {
        if (IrisCompat.isRenderingShadowPass()) {
            return;
        }
        float age = entity.age + tickDelta;
        float height = Math.max(0.7F, entity.getHeight());
        float radius = Math.max(0.31F, entity.getWidth() * 0.54F) + 0.035F;
        int count = Math.min(5, Math.max(1, style.density()));
        long seed = entity.getUuid().getLeastSignificantBits();
        float bodyYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevBodyYaw, entity.bodyYaw)
                * MathHelper.RADIANS_PER_DEGREE;
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        VertexConsumer dark = consumers.getBuffer(RenderLayer.getDebugQuads());
        for (int i = 0; i < count; i++) {
            drawWoundBase(dark, matrix, seed, i, count, height, radius, bodyYaw,
                    style.primaryColor());
        }

        VertexConsumer glow = consumers.getBuffer(RenderLayer.getEntityTranslucentEmissive(WHITE_TEXTURE));
        for (int i = 0; i < count; i++) {
            drawWoundRim(glow, matrix, seed, i, count, height, radius, bodyYaw,
                    style.primaryColor());
        }
        for (int i = 0; i < count; i++) {
            drawWoundEnergy(glow, matrix, age, seed, i, count, height, radius, bodyYaw,
                    style.primaryColor(), style.coreColor());
        }
        drawWoundMotes(glow, matrix, age, seed, count, height, radius, bodyYaw, style.coreColor());
    }

private static void drawWoundRim(VertexConsumer vertices, Matrix4f matrix,
                                     long seed, int index, int count, float height,
                                     float radius, float bodyYaw, int primaryColor) {
        float angle = woundAngle(seed, index, count, bodyYaw);
        Vec3d outward = new Vec3d(MathHelper.sin(angle), 0.0, MathHelper.cos(angle));
        Vec3d tangent = new Vec3d(outward.z, 0.0, -outward.x);
        float tilt = woundTilt(seed, index);
        Vec3d longAxis = tangent.multiply(MathHelper.cos(tilt)).add(UP.multiply(MathHelper.sin(tilt)));
        Vec3d shortAxis = UP.multiply(MathHelper.cos(tilt)).subtract(tangent.multiply(MathHelper.sin(tilt)));
        float halfLength = woundHalfLength(seed, index, height);
        float halfWidth = woundHalfWidth(seed, index, halfLength);
        Vec3d center = woundCenter(seed, index, height, radius, outward);
        int brightPurple = scaleColor(primaryColor, 1.62F);
        for (int segment = 0; segment < WOUND_SEGMENTS; segment++) {
            int next = (segment + 1) % WOUND_SEGMENTS;
            Vec3d outerA = woundPoint(seed, index, segment, center, outward, longAxis, shortAxis,
                    halfLength, halfWidth, 0.98F, 0.011F);
            Vec3d outerB = woundPoint(seed, index, next, center, outward, longAxis, shortAxis,
                    halfLength, halfWidth, 0.98F, 0.011F);
            Vec3d innerB = woundPoint(seed, index, next, center, outward, longAxis, shortAxis,
                    halfLength, halfWidth, 0.66F, 0.014F);
            Vec3d innerA = woundPoint(seed, index, segment, center, outward, longAxis, shortAxis,
                    halfLength, halfWidth, 0.66F, 0.014F);
            int color = (segment & 1) == 0 ? primaryColor : brightPurple;
            int alpha = (segment & 1) == 0 ? 198 : 226;
            woundGlowDoubleQuad(vertices, matrix, outerA, outerB, innerB, innerA, outward, color, alpha);
        }
    }

private static void renderGloamTendrils(LivingEntity entity, float tickDelta,
                                             ObserverStatusVisualStyle style, int stage,
                                             MatrixStack matrices,
                                             VertexConsumerProvider consumers) {
        if (!canRenderGloamAccent(entity)) {
            return;
        }
        float age = entity.age + tickDelta;
        Vec3d targetPosition = lerpedEntityPosition(entity, tickDelta);
        GloamTendrilState state = updateGloamTendrilState(
                entity, stage, age, targetPosition, style.scale());
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer vertices = consumers.getBuffer(RenderLayer.getDebugQuads());
        int color = style.primaryColor();
        int alpha = 138;
        for (int index = 0;
             index < GLOAM_TENDRIL_SLOTS && gloamAccentsThisFrame < 24;
             index++) {
            AnchoredGloamTendril tendril = state.tendrils[index];
            if (tendril == null) {
                continue;
            }
            renderAnchoredGloamTendril(vertices, matrix, entity, tendril,
                    index, targetPosition, age, color, alpha);
            gloamAccentsThisFrame++;
        }
    }

private void renderArmorLayer(EntityLivingBase living, float limbSwing, float limbSwingAmount, float delta, float age, float headYaw, float headPitch, float scale, EntityEquipmentSlot slot) {
	ItemStack stack = living.getItemStackFromSlot(slot);
	Item item = stack.getItem();
	if (item instanceof ItemArmor) {
		ItemArmor itemarmor = (ItemArmor) item;
		if (itemarmor.getEquipmentSlot() == slot) {
			ArmorRenderer armor = getModel(living, stack, slot, getModelFromSlot(slot));
			armor.setup(living, limbSwing, limbSwingAmount, delta, slot);
			//noinspection ConstantConditions
			rower.bindTexture(getArmorResource(living, stack, slot, null));
			if (itemarmor.hasOverlay(stack)) {
				int rgb = itemarmor.getColor(stack);
				float r = (float) (rgb >> 16 & 255) / 255.0F;
				float g = (float) (rgb >> 8 & 255) / 255.0F;
				float b = (float) (rgb & 255) / 255.0F;
				GlStateManager.color(r, g, b, 1.0F);
				armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
				rower.bindTexture(getArmorResource(living, stack, slot, "overlay"));
			}
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
			armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
			if (stack.hasEffect()) {
				glint.render(living, armor, limbSwing, limbSwingAmount, delta, age, headYaw, headPitch, scale, slot);
			}
		}
	}
}

@Override
public void render(PoseStack poseStack, MultiBufferSource buffer, int packedLight, ArmorStand livingEntity, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
    SlotTypeReference identifier = CapeItem.getStaticIdentifier();
    AccessoriesCapability accessories = AccessoriesCapability.get(livingEntity);
    if (accessories != null) {
        AccessoriesContainer accessoriesContainer = accessories.getContainer(identifier);
        if (accessoriesContainer != null) {
            ItemStack itemStack = accessoriesContainer.getAccessories().getItem(0);
            if (!itemStack.isEmpty()) {
                if (itemStack.getItem() instanceof CapeItem capeItem) {
                    ResourceLocation texture = capeItem.getCapeTexture();
                    for (Map.Entry<Predicate<ItemStack>, ResourceLocation> entry : AetherClient.CAPE_SECRETS.entrySet()) {
                        if (entry.getKey().test(itemStack)) {
                            texture = entry.getValue();
                            break;
                        }
                    }
                    if (!livingEntity.isInvisible() && texture != null) {
                        ItemStack itemstack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
                        if (!itemstack.is(Items.ELYTRA)) {
                            poseStack.pushPose();
                            poseStack.translate(0.0F, 0.0F, 0.0925F);
                            poseStack.mulPose(Axis.XP.rotationDegrees(3.0F));
                            poseStack.mulPose(Axis.ZP.rotationDegrees(0.0F));
                            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
                            VertexConsumer vertexconsumer = buffer.getBuffer(RenderType.entitySolid(texture));
                            this.cape.renderToBuffer(poseStack, vertexconsumer, packedLight, OverlayTexture.NO_OVERLAY);
                            poseStack.popPose();
                        }
                    }
                }
            }
        }
    }
}

	@Override
	public void render(@NotNull PoseStack pose, @NotNull MultiBufferSource buffer, int light, @NotNull ArmorStand armor, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
		if(!UsesForCursesModule.staticEnabled || !UsesForCursesModule.bindArmorStandsWithPlayerHeads) return;

		ItemStack head = armor.getItemBySlot(EquipmentSlot.HEAD);
		if(head.is(Items.PLAYER_HEAD) && EnchantmentHelper.has(head, EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE)) {

            RenderType rendertype;
            boolean slim = true;
            if (head.has(DataComponents.PROFILE)) {
                GameProfile profile = head.get(DataComponents.PROFILE).gameProfile();
                rendertype = SkullBlockRenderer.getRenderType(SkullBlock.Types.PLAYER, new ResolvableProfile(profile));
                PlayerSkin playerSkin = Minecraft.getInstance().getSkinManager().getInsecureSkin(profile);
                slim = playerSkin.model().equals(PlayerSkin.Model.SLIM);
            } else {
                rendertype =  RenderType.entityTranslucent(DefaultPlayerSkin.getDefaultTexture());
            }
            pose.pushPose();

            if (armor.isBaby()) {
                float s = 1F;
                pose.translate(0F, 0F, 0F);
                pose.scale(s, s, s);
            } else {
                float s = 2F;
                pose.translate(0F, -1.5F, 0F);
                pose.scale(s, s, s);
            }

            PlayerModel<?> model = slim ? playerModelSlim : playerModel;


            model.head.visible = false;
            model.hat.visible = false;

            rotateModel(model.leftArm, armor.getLeftArmPose());
            rotateModel(model.rightArm, armor.getRightArmPose());
            rotateModel(model.leftSleeve, armor.getLeftArmPose());
            rotateModel(model.rightSleeve, armor.getRightArmPose());

            rotateModel(model.leftLeg, armor.getLeftLegPose());
            rotateModel(model.rightLeg, armor.getRightLegPose());
            rotateModel(model.leftPants, armor.getLeftLegPose());
            rotateModel(model.rightPants, armor.getRightLegPose());

            model.renderToBuffer(pose, buffer.getBuffer(rendertype), light, OverlayTexture.NO_OVERLAY, -1);

            pose.popPose();

        }
	}

public void render(PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int outlineColor, int tintColor, boolean renderFoil) {
            if (!opaque.isEmpty()) {
                submitModel(nodeCollector, poseStack, opaque, lightCoords, outlineColor, tintColor, NO_TINT, MekanismRenderType.MEKASUIT);
                if (renderFoil) {
                    submitModel(nodeCollector.order(1), poseStack, opaque, lightCoords, EntityRenderState.NO_OUTLINE, tintColor, BASE_GLINT, MekanismRenderType.MEKASUIT_GLINT);
                }
            }
            if (!emissive.isEmpty()) {
                nodeCollector.submitBlockModel(poseStack, EMISSIVE, emissive, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                if (renderFoil) {
                    nodeCollector.order(1).submitBlockModel(poseStack, BASE_GLINT, emissive, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY,
                          EntityRenderState.NO_OUTLINE);
                }
            }
            if (!translucent.isEmpty()) {
                nodeCollector.submitBlockModel(poseStack, TRANSLUCENT, translucent, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                if (renderFoil) {
                    nodeCollector.order(1).submitBlockModel(poseStack, MekanismRenderType.ARMOR_TRANSLUCENT_GLINT, translucent,
                          BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
                }
            }
        }

private static void addQuadsToRender(ModelPos pos, String name, Map<String, OverrideData> overrides, Map<MekaSuitArmor.ModelPos, Set<String>> quadsToRender,
          Map<OBJModelData, Map<ModelPos, Set<String>>> specialQuadsToRender) {
        OverrideData override = overrides.get(name);
        if (override != null) {
            //Update the name and the target quads if there is an override
            name = override.name();
            // Note: In theory the special quads should have our model data corresponding
            // to a map already, but on the off chance they don't compute and add it
            OBJModelData overrideData = override.modelData();
            quadsToRender = specialQuadsToRender.computeIfAbsent(overrideData, _ -> new EnumMap<>(ModelPos.class));
        }
        quadsToRender.computeIfAbsent(pos, _ -> new HashSet<>()).add(name);
    }

public static void shootArrow(World world, LivingEntity shooter, RegistryEntry<Spell> spellEntry, SpellExecution.ImpactContext context, int sequenceIndex) {
        var spell = spellEntry.value();
        var shoot_arrow = spell.deliver.shoot_arrow;
        var weaponStack = shooter.getMainHandStack();

        // var weapon = weaponStack.getItem();
        // Using CROSSBOW statically, so arrows fired behave consistently
        // When using any bow, divergence is applied in an unhelpful manner
        var weapon = Items.CROSSBOW;
        if (shoot_arrow != null
                && (world instanceof ServerWorld serverWorld)
                && (weapon instanceof RangedWeaponItem rangedWeapon)) {
            var mutableLaunchProperties = shoot_arrow.launch_properties.copy();
            if (shooter instanceof PlayerEntity player) {
                var spellModifiers = SpellModifiers.of(player, spellEntry);
                for (var modifier: spellModifiers) {
                    if (modifier.projectile_launch != null) {
                        mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
                    }
                }
            }

            ItemStack ammo;
            if (shooter instanceof PlayerEntity player) {
                ammo = player.getProjectileType(weaponStack);
            } else {
                ammo = new ItemStack(Items.ARROW);
            }
            var loadedAmmo = RangedWeaponAccessor.load_SpellEngine(weaponStack, ammo, shooter);
            if (loadedAmmo.isEmpty()) {
                return;
            }

            // Save as active spell
            if (shooter instanceof SpellCaster.Player caster) {
                var shotContext = caster.getArrowShootContext();
                shotContext.firedBySpell = true;
                shotContext.activeSpells.add(spellEntry);
            }
            var divergence = (sequenceIndex == 0) ? 0F : shoot_arrow.divergence;
            // Perform shoot
            ((RangedWeaponAccessor) rangedWeapon).shootAll_SpellEngine(
                    serverWorld,
                    shooter,
                    Hand.MAIN_HAND,
                    weaponStack,
                    loadedAmmo,
                    shoot_arrow.launch_properties.velocity,
                    divergence,
                    shoot_arrow.arrow_critical_strike,
                    null);
            // Arrow perks applied by `RangedWeaponItemMixin`

            // Fixing inconsistent Vanille code, shoot sound is played by `BOW` outside of `shootAll`
            if (weapon instanceof BowItem) {
                world.playSound(
                        null,
                        shooter.getX(),
                        shooter.getY(),
                        shooter.getZ(),
                        SoundEvents.ENTITY_ARROW_SHOOT,
                        SoundCategory.PLAYERS,
                        1.0F,
                        1.0F / (world.getRandom().nextFloat() * 0.4F + 1.2F) + 1 * 0.5F
                );
            }

            if (shooter instanceof SpellCaster.Player caster) {
                caster.setArrowShootContext(ArrowShootContext.empty());
            }

            var extra_launch = mutableLaunchProperties.extra_launch_count;
            if (sequenceIndex == 0 && extra_launch > 0) {
                for (int i = 0; i < extra_launch; i++) {
                    var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                    var nextSequenceIndex = i + 1;
                    ((WorldScheduler)world).schedule(ticks, () -> {
                        if (shooter == null || !shooter.isAlive()) {
                            return;
                        }
                        shootArrow(world, shooter, spellEntry, context, nextSequenceIndex);
                    });
                }
            }
        }
    }

