public static WorldParticleBuilder cultistSigil(Level level, ColorParticleData colorData) {
        RandomSource rand = level.random;
        var scaleData = GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(rand, 0.5f, 0.6f), 0.5f)
                .setEasing(Easing.SINE_IN)
                .setCoefficient(Easing.SINE_IN_OUT.asWeighedRandom(rand, 1f, 1.25f)).build();
        return WorldParticleBuilder.create(MalumParticles.CULTIST_SIGIL.get())
                .setTransparencyData(GenericParticleData.create(0.95f, 0.7f).setEasing(Easing.SINE_IN_OUT).build())
                .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                .setScaleData(scaleData)
                .setColorData(colorData)
                .setLifetime(35)
                .enableNoClip()
                .setFriction(0.98f);
    }

public static int applyLuminosity(int packedLight, int luminosity) {
    // if full bright, skip some math
    if (luminosity >= 15) {
      return TintedArmorTexture.MAX_LIGHT;
    }
    // inlined version of methods from LightTexture
    return Math.max(luminosity, (packedLight & 0xFFFF) >> 4) << 4
      | Math.max(luminosity, packedLight >> 20 & 0xFFFF) << 20;
  }

@Override
  public ArmorTexture getArmorTexture(ItemStack stack, TextureType type, RegistryAccess access) {
    CompoundTag tag = stack.getTag();
    if (tag != null && tag.contains(ToolStack.TAG_MATERIALS, Tag.TAG_LIST)) {
      String material = tag.getList(ToolStack.TAG_MATERIALS, Tag.TAG_STRING).getString(index);
      if (!material.isEmpty() && cache.computeIfAbsent(material, this)) {
        return apply.getArmorTexture(stack, type, access);
      }
    }
    return ArmorTexture.EMPTY;
  }

@Override
  public Boolean apply(String string) {
    MaterialVariantId material = MaterialVariantId.tryParse(string);
    if (material != null) {
      return MaterialRenderInfoLoader.INSTANCE.hasFallback(material, fallback);
    }
    return false;
  }

@Override
protected void renderModelPart(PoseStack poseStack, MultiBufferSource bufferSource, ItemStack stack, LivingEntity entity, EquipmentSlot slot, int light, int dyeColor, HumanoidModel<LivingEntity> contextModel, ArcanistRobesModel<LivingEntity> armorModel) {
	if(stack.getItem() instanceof ArcanistRobesItem wizardArmor) {
		int hexColor = wizardArmor.getColor(stack);

		if(stack.has(DataComponents.CUSTOM_NAME) && stack.getHoverName().getString().equals("jeb_")) {
			int interval = 15;
			int idfk = entity.tickCount / interval + entity.getId();
			int colorCount = DyeColor.values().length;
			float f = ((entity.tickCount % interval) + Minecraft.getInstance().getFrameTimeNs()) / 15f;
			int color1 = Sheep.getColor(DyeColor.byId(idfk % colorCount));
			int color2 = Sheep.getColor(DyeColor.byId((idfk + 1) % colorCount));
			hexColor = FastColor.ARGB32.lerp(f, color1, color2);
		}

		model.renderToBuffer(poseStack, ItemRenderer.getArmorFoilBuffer(bufferSource, RenderType.armorCutoutNoCull(mainTexture), false), light, OverlayTexture.NO_OVERLAY, hexColor);
		model.renderToBuffer(poseStack, ItemRenderer.getArmorFoilBuffer(bufferSource, RenderType.armorCutoutNoCull(overlayTexture), false), light, OverlayTexture.NO_OVERLAY, 0xffffffff);
	}
}

@Override
public @NotNull Model getGenericArmorModel(@NotNull LivingEntity entity, @NotNull ItemStack itemStack, @NotNull EquipmentSlot armorSlot, @NotNull HumanoidModel playerModel) {
    var model = super.getGenericArmorModel(entity, itemStack, armorSlot, playerModel);
    if (armorSlot.equals(EquipmentSlot.CHEST)) {
        var skin = itemStack.get(MalumDataComponents.APPLIED_ITEM_SKIN);
        RenderTypeToken scarfToken = skin != null ?
                RenderTypeToken.createToken(skin.name().withPrefix("textures/vfx/scarf/").withSuffix(".png"))
                : MalumRenderTypeTokens.SCARF;
        ScarfRenderHandler.addScarfRenderer(entity, (consumer) -> {
            boolean noSkin = skin == null;
            int scarfCount = noSkin ? 2 : 1;
            float scale = noSkin ? 0.35f : 0.4f;
            float endingScale = noSkin ? 0.45f : 1f;
            float offset = noSkin ? 0.25f : 0.2f;
            for (int i = 0; i < scarfCount; i++) {
                var data = new ScarfRenderHandler.ScarfRenderData(scarfToken, ClientConfig.SCARF_LENGTH.getConfigValue())
                        .setPredicate(() -> {
                            ItemStack stack = entity.getItemBySlot(armorSlot);
                            return !stack.isEmpty() && stack.is(itemStack.getItem());
                        })
                        .setScale(scale)
                        .setEndingScale(endingScale)
                        .setHorizontalOffset(i == 0 ? -offset : offset);
                if (noSkin) {
                    data.setSecondaryColor(new Color(150, 150, 150));
                }
                consumer.accept(data);
            }
        });
    }
    return model;
}

private int collectRenderPoints(TrailParticle particle, Vector3f cameraPos, float partialTicks) {
        var tails = particle.getTails();
        var rawTails = particle.getRawTails();
        var color = particle.getRealColor(partialTicks);
        scratchLight = particle.getRealLight(partialTicks);

        Vector3f headPos = particle.getHeadPosition(partialTicks);
        int tailSize = tails.size();
        boolean pushHead = true;
        if (tailSize > 0) {
            Vector3f lastPos = tails.getPosition(tailSize - 1);
            if (lastPos.equals(headPos)) {
                pushHead = false;
            }
        }
        // logical point list = tails plus (optionally) the head; n mirrors the CPU strip's size
        int n = tailSize + (pushHead ? 1 : 0);
        if (n < 2) return 0;

        var lerpDur = 0f;
        var t = 0f;
        if (rawTails.size() > 1) {
            lerpDur = rawTails.getLifeTime(1) - rawTails.getLifeTime(0);
            t = 1 - (rawTails.getLifeTime(0) + 1 - partialTicks) / lerpDur;
        }

        // first rendered segment k — the skipped segments form a prefix (lifetimes grow with index)
        int k = -1;
        boolean lerpFirst = false;
        float lerpFactor = 0;
        for (int i = 0; i < n - 1; i++) {
            float lifeI = (pushHead && i == n - 1) ? 100 : tails.getLifeTime(i);
            float lifeI1 = (pushHead && i + 1 == n - 1) ? 100 : tails.getLifeTime(i + 1);
            if (lifeI - partialTicks < 0f && lifeI1 - partialTicks < 0) continue;
            var currT = lifeI / lerpDur;
            var nextT = lifeI1 / lerpDur;
            if (nextT < t) continue;
            k = i;
            if (lerpDur > 0 && currT <= t && t <= nextT) {
                lerpFirst = true;
                lerpFactor = (t - currT) / (nextT - currT);
            }
            break;
        }
        if (k == -1) return 0;

        int count = n - k;
        ensureScratch(count);
        float lifetime = Math.max(particle.getLifetimeSupplier().get(), 1.0E-5f);
        float uLast = 0;

        for (int j = k; j < n; j++) {
            int idx = j - k;
            boolean isPushedHead = pushHead && j == n - 1;

            Vector3f pos = isPushedHead ? headPos : tails.getPosition(j);
            if (j == k && lerpFirst) {
                Vector3f next = (pushHead && j + 1 == n - 1) ? headPos : tails.getPosition(j + 1);
                pos = new Vector3f(pos).lerp(next, lerpFactor);
            }
            px[idx] = pos.x - cameraPos.x;
            py[idx] = pos.y - cameraPos.y;
            pz[idx] = pos.z - cameraPos.z;

            // the pushed head reuses the OLDEST tail's color/width (CPU quirk — keep it)
            float tcr, tcg, tcb, tca, tw;
            if (isPushedHead) {
                if (tailSize > 0) {
                    var headColor = tails.getColor(0);
                    tcr = headColor.x();
                    tcg = headColor.y();
                    tcb = headColor.z();
                    tca = headColor.w();
                    tw = tails.getWidth(0);
                } else {
                    tcr = tcg = tcb = tca = 1;
                    tw = 0;
                }
            } else {
                var tailColor = tails.getColor(j);
                tcr = tailColor.x();
                tcg = tailColor.y();
                tcb = tailColor.z();
                tca = tailColor.w();
                tw = tails.getWidth(j);
            }
            cr[idx] = color.x() * tcr;
            cg[idx] = color.y() * tcg;
            cb[idx] = color.z() * tcb;
            ca[idx] = color.w() * tca;
            width[idx] = tw;

            // per-point u: segment j's u0; the head point continues with the last segment's u1
            if (j <= n - 2) {
                var uvs = particle.getUVs(j, n, partialTicks);
                u[idx] = uvs.x();
                if (j == k) {
                    scratchV0 = uvs.y();
                    scratchV1 = uvs.w();
                }
                if (j == n - 2) {
                    uLast = uvs.z();
                }
            } else {
                u[idx] = uLast;
            }

            // per-point channels
            pointT[idx] = j / (n - 1f);
            float life = isPushedHead ? 100 : tails.getLifeTime(j);
            pointLife[idx] = 1 - Math.min(Math.max(life / lifetime, 0f), 1f);
        }
        return count;
    }

private void emissionStep(float time) {
        // Acumulate the amount of time passed:
        accumTime += time;

        // If enough time has passed since the last emission (>= timeInterval), consider emitting new points.
        if (accumTime >= runtime.timeInterval.get()) {
            if (config.emit) {
                var position = getWorldToTrail().transformPosition(getWorldPosition());

                // If there's less than 2 points, or if the last 2 points are too far apart, spawn a new one:
                if (points.isEmpty() || (
                        position.distance(points.getLast().position) >= runtime.minDistance.get()
                )) {
                    emitPoint(position);
                    accumTime = 0;
                }
            }
        }
    }

@Override
public void doRender(EntityPredatorArrowGuide entity, double x, double y, double z, float entityYaw, float partialTicks) {
	super.doRender(entity, x, y, z, entityYaw, partialTicks);

	Entity target = entity.getTarget();
	Entity ridingEntity = entity.getRidingEntity();

	if(target != null) {
		double ix = entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks;
		double iy = entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks;
		double iz = entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks;

		double targetIx = target.lastTickPosX + (target.posX - target.lastTickPosX) * partialTicks;
		double targetIy = target.lastTickPosY + (target.posY - target.lastTickPosY) * partialTicks + target.getEyeHeight();
		double targetIz = target.lastTickPosZ + (target.posZ - target.lastTickPosZ) * partialTicks;

		double diffX = targetIx - ix;
		double diffY = targetIy - iy;
		double diffZ = targetIz - iz;

		LightingUtil.INSTANCE.setLighting(255);

		GlStateManager.disableLighting();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0);
		GlStateManager.disableCull();
		GlStateManager.depthMask(false);

		this.bindTexture(BEAM_TEXTURE);

		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y - (ridingEntity != null ? (entity.posY - ridingEntity.posY) : 0), z);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		ParticleBeam.buildBeam(diffX, diffY, diffZ, new Vec3d(-diffX, -diffY, -diffZ), 0.05F, 0, 2F,
				ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
				(vx, vy, vz, u, v) -> {
					buffer.pos(vx, vy, vz).tex(u, v).color(35, 80, 110, 255).endVertex();
				});

		tessellator.draw();

		GlStateManager.popMatrix();

		GlStateManager.depthMask(true);
		GlStateManager.enableCull();
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
		GlStateManager.disableBlend();
		GlStateManager.enableLighting();

		LightingUtil.INSTANCE.revert();
	}
}

@Override
	public void renderItemInHand(ItemStack stack, LivingEntityPatch<?> entitypatch, InteractionHand hand, OpenMatrix4f[] poses, MultiBufferSource buffer, PoseStack poseStack, int packedLight, float partialTicks) {
        // The blade renders at the joint of whichever hand actually holds it; the sheath rides on
        // the opposite hand. The original implementation hardcoded MAIN_HAND for the blade and
        // OFF_HAND for the sheath, which left the katana stuck on the right side and the sheath
        // invisible whenever the player swapped to mirror mode. Following the live `hand` argument
        // makes both pieces follow the X-flip applied at ClientAnimator.getPose, so they appear on
        // the correct sides without authoring a mirrored variant. The display context stays
        // THIRD_PERSON_RIGHT_HAND for both pieces -- the underlying data is always authored
        // right-handed, and the pose mirror plus the side-aware parent joint already handle the
        // visual flip; switching the display context on top would double-mirror and offset the
        // model from the hand.
        InteractionHand sheathHand = (hand == InteractionHand.MAIN_HAND) ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND;

        OpenMatrix4f modelMatrix = this.getCorrectionMatrix(entitypatch, hand, poses);
		poseStack.pushPose();
		MathUtils.mulStack(poseStack, modelMatrix);
        itemRenderer.renderStatic(stack, ItemDisplayContext.THIRD_PERSON_RIGHT_HAND, packedLight, OverlayTexture.NO_OVERLAY, poseStack, buffer, null, 0);
        poseStack.popPose();
        if (entitypatch.getHoldingItemCapability(hand) instanceof WeaponCapability wCap && wCap.getCurrentSet(entitypatch) instanceof Moveset set && set.shouldRenderSheath().test(entitypatch))
        {
            modelMatrix = this.getCorrectionMatrix(entitypatch, sheathHand, poses);
            poseStack.pushPose();
            MathUtils.mulStack(poseStack, modelMatrix);
            itemRenderer.renderStatic(this.sheathStack, ItemDisplayContext.THIRD_PERSON_RIGHT_HAND, packedLight, OverlayTexture.NO_OVERLAY, poseStack, buffer, null, 0);
            poseStack.popPose();
        }

    }

