@Override
	protected void setupPoseStack(PoseStack poseStack, Camera camera, float partialTick) {
		poseStack.pushPose();
		Vec3 cameraPosition = camera.getPosition();
		float x = (float) (Mth.lerp(partialTick, this.xo, this.x) - cameraPosition.x());
		float y = (float) (Mth.lerp(partialTick, this.yo, this.y) - cameraPosition.y());
		float z = (float) (Mth.lerp(partialTick, this.zo, this.z) - cameraPosition.z());
		poseStack.translate(x, y, z);
		Quaternionf rotation = new Quaternionf(0.0F, 0.0F, 0.0F, 1.0F);
		/*
		 * rotate the particle by entity's model matrix
		 * uncomment and revert to this code when problem occurs with model matrix
		float roll = Mth.rotLerp(partialTick, this.oRoll, this.roll);
		float pitch = Mth.rotLerp(partialTick, this.pitchO, this.pitch);
		float yaw = Mth.rotLerp(partialTick, this.yawO, this.yaw);
		rotation.mul(QuaternionUtils.YP.rotationDegrees(180.0F - this.yaw));
		rotation.mul(QuaternionUtils.XP.rotationDegrees(pitch));
		rotation.mul(QuaternionUtils.ZP.rotationDegrees(roll));
		*/
		rotation.mul(QuaternionUtils.YP.rotationDegrees(180.0F));
		poseStack.mulPose(rotation);
		poseStack.mulPose(OpenMatrix4f.exportToMojangMatrix(this.entitySnapshot.getModelMatrix()));

		float scale = Mth.lerp(partialTick, this.scaleO, this.scale);
		poseStack.translate(0.0F, this.entitySnapshot.getHeightHalf(), 0.0F);
		poseStack.scale(scale, scale, scale);
		poseStack.translate(0.0F, -this.entitySnapshot.getHeightHalf(), 0.0F);
	}

@Override
		public void render(VertexConsumer vertexConsumer, Camera camera, float partialTick) {
			float alpha = Mth.lerp(partialTick, this.alphaO, this.alpha);
			int lightColor = this.getLightColor(partialTick);
			PoseStack poseStack = new PoseStack();
			this.setupPoseStack(poseStack, camera, partialTick);
			MultiBufferSource.BufferSource buffers = Minecraft.getInstance().renderBuffers().bufferSource();
			this.entitySnapshot.renderTextured(poseStack, buffers, EpicFightRenderTypes::entityAfterimageStencil, Mesh.DrawingFunction.POSITION_TEX, 0, 0.0F, 0.0F, 0.0F, 1.0F);
			this.entitySnapshot.renderItems(poseStack, buffers, EpicFightRenderTypes.itemAfterimageStencil(), Mesh.DrawingFunction.POSITION_TEX, lightColor, 1.0F);
			buffers.endLastBatch();

			this.entitySnapshot.render(poseStack, buffers, EpicFightRenderTypes.entityAfterimageWhite(), Mesh.DrawingFunction.POSITION_TEX_COLOR_LIGHTMAP, lightColor, this.rCol, this.gCol, this.bCol, alpha);
			this.entitySnapshot.renderItems(poseStack, buffers, EpicFightRenderTypes.itemAfterimageWhite(), Mesh.DrawingFunction.POSITION_TEX_COLOR_LIGHTMAP, lightColor, alpha);
			buffers.endLastBatch();
			this.revert(poseStack);
		}

public static void renderOverlay(@Nullable Entity entity, Runnable renderer, boolean glow, float red, float green, float blue, float alpha) {
		GlStateManager.doPolygonOffset(-0.01F, -3.0F);
		GlStateManager.enablePolygonOffset();

		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.depthMask(false);
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(red, green, blue, alpha);

		if(glow) {
			int i = 61680;
			int j = i % 65536;
			int k = i / 65536;
			OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, (float)j, (float)k);
			GlStateManager.disableLighting();
	    }

		renderer.run();

		if(glow) {
			GlStateManager.depthMask(entity == null || !entity.isInvisible());
			GlStateManager.color(red * alpha, green * alpha, blue * alpha, alpha);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);

			renderer.run();

			if(entity != null) {
				setLightmap(entity);
			}
		}

		GlStateManager.enableLighting();

		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		GlStateManager.doPolygonOffset(0.0F, 0.0F);
		GlStateManager.disablePolygonOffset();
	}

private BloodSnapshot buildBloodSnapshot(World world, float tickDelta,
                                             int style, boolean standaloneDevourer,
                                             MergedStainState renderState) {
        List<BloodEntityState> states = new ArrayList<>();
        Set<UUID> loaded = new HashSet<>();
        for (BloodStainVisualEntity entity : bloodEntities(world)) {
            loaded.add(entity.getUuid());
            if (entity.getStyle() != style) {
                continue;
            }
            if (style == BloodStainVisualEntity.STYLE_DEVOURER
                    && (entity.getSourceEntityId() < 0) != standaloneDevourer) {
                continue;
            }
            float opacity = bloodOpacity(entity, tickDelta);
            if (opacity <= 0.01F || entity.getRadius() <= 0.05F) {
                continue;
            }
            double centerX = MathHelper.lerp(tickDelta, entity.prevX, entity.getX());
            double centerY = MathHelper.lerp(tickDelta, entity.prevY, entity.getY());
            double centerZ = MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ());
            float yaw = MathHelper.lerpAngleDegrees(
                    tickDelta, entity.prevYaw, entity.getYaw())
                    * MathHelper.RADIANS_PER_DEGREE;
            long shapeKey;
            SplatterShape organicShape;
            if (entity.getShape() == BloodStainVisualEntity.SHAPE_TRAIL) {
                shapeKey = shapeKey(3 + style * 10, entity.getHalfLength(),
                        entity.getRadius(), yaw, entity.getSeed());
                organicShape = getBloodShape(entity.getUuid(), shapeKey,
                        () -> bloodTrailShape(entity.getHalfLength(),
                                entity.getRadius(), yaw, entity.getSeed()));
            } else {
                shapeKey = shapeKey(2 + style * 10, entity.getRadius(),
                        0.0F, 0.0F, entity.getSeed());
                organicShape = getBloodShape(entity.getUuid(), shapeKey,
                        () -> bloodPoolShape(entity.getRadius(), entity.getSeed()));
            }
            long maskKey = maskKey(shapeKey, centerX, centerZ);
            BloodMaskCache maskCache = this.bloodMasks.get(entity.getUuid());
            if (maskCache == null || maskCache.maskKey != maskKey) {
                maskCache = new BloodMaskCache(maskKey,
                        rasterizeBloodShape(
                                organicShape, centerX, centerZ, BLOOD_FINE_GRID_SCALE),
                        null);
                this.bloodMasks.put(entity.getUuid(), maskCache);
            }
            if (!maskCache.fineCells.isEmpty()) {
                states.add(new BloodEntityState(
                        entity.getUuid(), maskKey, maskCache,
                        centerY - entity.getVerticalRange(),
                        centerY + entity.getVerticalRange(),
                        opacity, entity.age));
            }
        }
        this.bloodMasks.keySet().removeIf(id -> !loaded.contains(id));
        this.bloodShapes.keySet().removeIf(id ->
                !loaded.contains(id) && !this.caches.containsKey(id));
        return buildMergedSnapshot(world, states, renderState);
    }

private DevourerTrailSnapshot buildDevourerTrailSnapshot(
            World world, int sourceEntityId, float tickDelta) {
        LongOpenHashSet cells = new LongOpenHashSet();
        Set<UUID> loaded = new HashSet<>();
        double minY = Double.POSITIVE_INFINITY;
        double maxY = Double.NEGATIVE_INFINITY;
        for (BloodStainVisualEntity entity : bloodEntities(world)) {
            loaded.add(entity.getUuid());
            if (entity.getStyle() != BloodStainVisualEntity.STYLE_DEVOURER
                    || entity.getSourceEntityId() != sourceEntityId
                    || entity.getRadius() <= 0.05F) {
                continue;
            }
            double entityX = MathHelper.lerp(tickDelta, entity.prevX, entity.getX());
            double entityY = MathHelper.lerp(tickDelta, entity.prevY, entity.getY());
            double entityZ = MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ());
            float yaw = MathHelper.lerpAngleDegrees(
                    tickDelta, entity.prevYaw, entity.getYaw())
                    * MathHelper.RADIANS_PER_DEGREE;
            long shapeKey;
            SplatterShape shape;
            if (entity.getShape() == BloodStainVisualEntity.SHAPE_TRAIL) {
                shapeKey = shapeKey(13, entity.getHalfLength(),
                        entity.getRadius(), yaw, entity.getSeed());
                shape = getBloodShape(entity.getUuid(), shapeKey,
                        () -> bloodTrailShape(entity.getHalfLength(),
                                entity.getRadius(), yaw, entity.getSeed()));
            } else {
                shapeKey = shapeKey(12, entity.getRadius(),
                        0.0F, 0.0F, entity.getSeed());
                shape = getBloodShape(entity.getUuid(), shapeKey,
                        () -> bloodPoolShape(entity.getRadius(), entity.getSeed()));
            }
            long maskKey = maskKey(shapeKey, entityX, entityZ);
            BloodMaskCache mask = this.bloodMasks.get(entity.getUuid());
            if (mask == null || mask.maskKey != maskKey) {
                mask = new BloodMaskCache(maskKey,
                        rasterizeBloodShape(
                                shape, entityX, entityZ, BLOOD_FINE_GRID_SCALE),
                        null);
                this.bloodMasks.put(entity.getUuid(), mask);
            }
            cells.addAll(coarseBloodMask(mask));
            minY = Math.min(minY, entityY - entity.getVerticalRange());
            maxY = Math.max(maxY, entityY + entity.getVerticalRange());
        }
        this.bloodMasks.keySet().removeIf(entityId -> !loaded.contains(entityId));
        this.bloodShapes.keySet().removeIf(entityId ->
                !loaded.contains(entityId) && !this.caches.containsKey(entityId));
        long[] ordered = cells.toLongArray();
        Arrays.sort(ordered);
        long signature = 0xcbf29ce484222325L;
        for (long cell : ordered) {
            signature = mixSignature(signature, cell);
        }
        signature = mixSignature(signature, ordered.length);
        return new DevourerTrailSnapshot(
                cells, signature, minY, maxY, !cells.isEmpty());
    }

private static void drawMoltenGeometry(
            double centerX, double centerY, double centerZ,
            MatrixStack.Entry matrices,
            VertexConsumerProvider vertexConsumers,
            BloodPreparedGeometry geometry, float[] sourceOpacities,
            boolean allOpaque) {
        SpriteAtlasTexture atlas = MinecraftClient.getInstance()
                .getBakedModelManager()
                .getAtlas(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE);
        Sprite magma = atlas.getSprite(MAGMA_TEXTURE);
        Sprite lava = atlas.getSprite(LAVA_TEXTURE);
        VertexConsumer opaque = vertexConsumers.getBuffer(RenderLayer.getCutout());
        if (allOpaque) {
            drawMoltenPatches(centerX, centerY, centerZ, matrices, opaque,
                    geometry.fillPatches, magma, 1.0F, false);
            drawMoltenPatches(centerX, centerY, centerZ, matrices, opaque,
                    geometry.borderPatches, lava, 1.0F, true);
            return;
        }
        for (BloodPreparedPatch patch : geometry.fillPatches) {
            float opacity = bloodPatchOpacity(patch.contributors, sourceOpacities);
            if (opacity >= 0.999F) {
                drawMoltenPatch(centerX, centerY, centerZ,
                        matrices, opaque, patch, magma, 1.0F, false);
            }
        }
        for (BloodPreparedPatch patch : geometry.borderPatches) {
            float opacity = bloodPatchOpacity(patch.contributors, sourceOpacities);
            if (opacity >= 0.999F) {
                drawMoltenPatch(centerX, centerY, centerZ,
                        matrices, opaque, patch, lava, 1.0F, true);
            }
        }
        VertexConsumer translucent = null;
        for (BloodPreparedPatch patch : geometry.fillPatches) {
            float opacity = bloodPatchOpacity(patch.contributors, sourceOpacities);
            if (opacity > 0.01F && opacity < 0.999F) {
                if (translucent == null) {
                    translucent = vertexConsumers.getBuffer(
                            RenderLayer.getEntityTranslucent(
                                    SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
                }
                drawMoltenPatch(centerX, centerY, centerZ,
                        matrices, translucent, patch, magma, opacity, false);
            }
        }
        for (BloodPreparedPatch patch : geometry.borderPatches) {
            float opacity = bloodPatchOpacity(patch.contributors, sourceOpacities);
            if (opacity > 0.01F && opacity < 0.999F) {
                if (translucent == null) {
                    translucent = vertexConsumers.getBuffer(
                            RenderLayer.getEntityTranslucent(
                                    SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
                }
                drawMoltenPatch(centerX, centerY, centerZ,
                        matrices, translucent, patch, lava, opacity, true);
            }
        }
    }

public static void windTrailParticles(Level level, RandomSource random, Entity target, Vec3 pos, MalumNetworkedParticleEffectColorData colorData, WindTrailParticleEffect.WindTrailParticleEffectData extraData) {
        int delay = extraData.delay();
        int duration = extraData.duration();
        var transparencyData = GenericParticleData.create(1f, 0.4f).setEasing(Easing.QUAD_IN).build();
        var builder = WorldParticleBuilder.create(MalumParticles.MOTION_LINES.get())
                .setBehavior(SparkParticleBehavior.sparkBehavior())
                .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                .setScaleData(GenericParticleData.create(1f, 0f))
                .setLengthData(GenericParticleData.create(0.75f))
                .setTransparencyData(transparencyData)
                .setColorData(colorData.getColor())
                .enableForcedSpawn()
                .setLifetime(30)
                .enableNoClip();
        for (int i = 0; i < duration; i++) {
            builder.setLifeDelay(delay + i)
                    .clearSpawnActors()
                    .addSpawnActor(p -> {
                        float offsetScale = 0.2f;
                        Vec3 offset = new Vec3(
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale),
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale),
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale)
                        );
                        var position = target.position().add(0, target.getBbHeight() / 2, 0).add(offset);
                        p.setParticlePosition(position);
                        p.setParticleSpeed(target.getDeltaMovement().scale(0.3f));
                    })
                    .spawn(level, pos);
        }
    }

@Override
	public void tick() {
		if (this.shouldRemove) {
			if (this.age >= this.lifetime) {
				this.remove();
			}
		} else {
			if (!this.canContinue()) {
				this.shouldRemove = true;
				this.lifetime = this.age + this.trailInfo.trailLifetime();
			}
		}

		this.age++;
		this.trailEdges.removeIf(v -> !v.isAlive());

		if (!this.canCreateNextCurve()) {
			return;
		}

		Vec3 lastPos = this.owner.getOriginal().getPosition(0.0F);
		double xd = Math.pow(this.owner.getOriginal().getX() - lastPos.x, 2);
		double yd = Math.pow(this.owner.getOriginal().getY() - lastPos.y, 2);
		double zd = Math.pow(this.owner.getOriginal().getZ() - lastPos.z, 2);
		float move = (float)Math.sqrt(xd + yd + zd) * 2.0F;

		this.setSize(this.bbWidth + move, this.bbHeight + move);
		this.createNextCurve();
	}

public static LayerDefinition createArmorLayer(CubeDeformation deformation) {
        MeshDefinition meshdefinition = HumanoidModel.createMesh(deformation, 0.0F);
